import React, {useCallback, useMemo, useState} from 'react';
import styled from 'styled-components';
import {useIntl} from 'react-intl';
import ReactSelect, {StylesConfig} from 'react-select';
import {WithTooltip} from '@workspace/shared/components/tooltip';

import ProfileSelector from 'src/components/profile/profile_selector';
import {useProfilesInTeam} from 'src/hooks';
import {
    AssigneeTypeCreator,
    AssigneeTypeOwner,
    AssigneeTypePropertyUser,
    ChecklistItem,
    isRoleBasedAssigneeType,
} from 'src/types/playbook';

import {PropertyField, PropertyFieldType, PropertyValue} from 'src/types/properties';
import {AssigneeOnlyCompleteControl} from 'src/components/checklist_item/assignee_only_complete_control';
import LocalizedSelectMenuPortal from 'src/components/widgets/localized_select_menu_portal';

import {isRtlLocale} from 'src/utils';

const ROLE_NONE = 'none';

type RoleOption = {value: string; label: string};

interface Props {
    checklistItem: ChecklistItem;
    editable: boolean;
    disabledReason?: string;
    onChanged: (item: ChecklistItem) => void;
    onAssigneeMenuOpenChange?: (isOpen: boolean) => void;
    participantUserIds: string[];
    runOwnerUserId?: string;
    runCreatorUserId?: string;
    mode?: 'template' | 'run';
    propertyFields?: PropertyField[];
    propertyValues?: PropertyValue[];
}

const AssigneeDropdown = ({checklistItem, editable, disabledReason, onChanged, onAssigneeMenuOpenChange, participantUserIds, runOwnerUserId, runCreatorUserId, mode, propertyFields, propertyValues}: Props) => {
    const {formatMessage, locale} = useIntl();
    const isRtl = isRtlLocale(locale);
    const selectStyles = useMemo(() => assigneeSelectStyles(isRtl), [isRtl]);
    const profilesInTeam = useProfilesInTeam();
    const [pendingPropertyUser, setPendingPropertyUser] = useState<boolean>(false);

    const assigneeType = checklistItem.assignee_type || '';

    const selectedRole = isRoleBasedAssigneeType(assigneeType) ? assigneeType : ROLE_NONE;

    // When the property_user radio is clicked but no field has been selected yet,
    // show it as selected in the UI without firing a mutation.
    const displayRole = pendingPropertyUser ? AssigneeTypePropertyUser : selectedRole;

    const handleRoleRadioChange = useCallback((value: string) => {
        if (value === AssigneeTypePropertyUser) {
            setPendingPropertyUser(true);
            return;
        }
        setPendingPropertyUser(false);
        onChanged({
            ...checklistItem,
            assignee_type: value === ROLE_NONE ? '' : value,
            assignee_id: '',
            assignee_property_field_id: '',
            assignee_only_complete: value === ROLE_NONE ? false : checklistItem.assignee_only_complete,
        });
    }, [checklistItem, onChanged]);

    const handlePropertyUserFieldChange = useCallback((fieldId: string) => {
        setPendingPropertyUser(false);
        onChanged({
            ...checklistItem,
            assignee_type: fieldId ? AssigneeTypePropertyUser : '',
            assignee_id: '',
            assignee_property_field_id: fieldId,
            assignee_only_complete: fieldId ? checklistItem.assignee_only_complete : false,
        });
    }, [checklistItem, onChanged]);

    const getAllUsersInTeam = useCallback(async () => profilesInTeam, [profilesInTeam]);

    const handleUserSelect = useCallback((user?: {id: string}) => {
        setPendingPropertyUser(false);
        onChanged({
            ...checklistItem,
            assignee_type: '',
            assignee_id: user?.id ?? '',
            assignee_property_field_id: '',
            assignee_only_complete: user?.id ? checklistItem.assignee_only_complete : false,
        });
    }, [checklistItem, onChanged]);

    const handleAssigneeOnlyCompleteChange = useCallback((value: boolean) => {
        onChanged({
            ...checklistItem,
            assignee_only_complete: value,
        });
    }, [checklistItem, onChanged]);

    const userPropertyFields = useMemo(
        () => propertyFields?.filter((f) => f.type === PropertyFieldType.User) ?? [],
        [propertyFields],
    );

    const roleOptions = useMemo(() => [
        {value: ROLE_NONE, label: formatMessage({defaultMessage: 'None'})},
        {value: AssigneeTypeOwner, label: formatMessage({defaultMessage: 'Run Owner — Resolves to run owner at creation'})},
        {value: AssigneeTypeCreator, label: formatMessage({defaultMessage: 'Run Creator — Resolves to run creator at creation'})},
        ...(userPropertyFields.length > 0 ? [{
            value: AssigneeTypePropertyUser,
            label: formatMessage({defaultMessage: 'Run User — Resolves to a user-type attribute at creation'}),
        }] : []),
    ], [formatMessage, userPropertyFields.length]);

    if (!editable && isRoleBasedAssigneeType(assigneeType)) {
        let resolvedUserId: string | undefined;
        let badgeLabel: string;
        let badgeTestId: string;

        if (assigneeType === AssigneeTypePropertyUser) {
            const field = propertyFields?.find((f) => f.id === checklistItem.assignee_property_field_id);
            badgeLabel = field ? formatMessage({defaultMessage: 'Run {name}'}, {name: field.name}) : formatMessage({defaultMessage: 'Run User'});
            badgeTestId = 'property-user-indicator-badge';
            if (mode === 'run') {
                const pv = propertyValues?.find((v) => v.field_id === checklistItem.assignee_property_field_id);
                if (pv?.value && typeof pv.value === 'string') {
                    resolvedUserId = pv.value;
                } else if (checklistItem.assignee_id) {
                    resolvedUserId = checklistItem.assignee_id;
                }
            }
        } else {
            badgeLabel = assigneeType === AssigneeTypeOwner ? formatMessage({defaultMessage: 'Run Owner'}) : formatMessage({defaultMessage: 'Run Creator'});
            badgeTestId = 'role-indicator-badge';
            if (mode === 'run') {
                resolvedUserId = checklistItem.assignee_id || (assigneeType === AssigneeTypeOwner ? runOwnerUserId : runCreatorUserId);
            }
        }

        return (
            <Container>
                {disabledReason && (
                    <DisabledReasonBanner data-testid='assignee-locked-reason'>
                        {disabledReason}
                    </DisabledReasonBanner>
                )}
                {resolvedUserId && (
                    disabledReason ? (
                        <WithTooltip
                            id='assignee-locked-editor-tooltip'
                            title={disabledReason}
                        >
                            <span>
                                <CompactProfileSelector
                                    selectedUserId={resolvedUserId}
                                    placeholder={formatMessage({defaultMessage: 'Assignee...'})}
                                    enableEdit={false}
                                    getAllUsers={getAllUsersInTeam}
                                    selfIsFirstOption={false}
                                />
                            </span>
                        </WithTooltip>
                    ) : (
                        <CompactProfileSelector
                            selectedUserId={resolvedUserId}
                            placeholder={formatMessage({defaultMessage: 'Assignee...'})}
                            enableEdit={false}
                            getAllUsers={getAllUsersInTeam}
                            selfIsFirstOption={false}
                        />
                    )
                )}
                <RoleBadge data-testid={badgeTestId}>
                    {badgeLabel}
                </RoleBadge>
            </Container>
        );
    }

    return (
        <Container>
            {!editable && disabledReason && (
                <DisabledReasonBanner data-testid='assignee-locked-reason'>
                    {disabledReason}
                </DisabledReasonBanner>
            )}
            <SectionLabel>{formatMessage({defaultMessage: 'ASSIGN TO A PERSON'})}</SectionLabel>
            {!editable && disabledReason ? (
                <WithTooltip
                    id='assignee-locked-editor-tooltip'
                    title={disabledReason}
                >
                    <span>
                        <ProfileSelector
                            testId={'assignee-profile-selector'}
                            selectedUserId={checklistItem.assignee_id}
                            placeholder={formatMessage({defaultMessage: 'Assignee...'})}
                            enableEdit={false}
                            getAllUsers={getAllUsersInTeam}
                            onSelectedChange={handleUserSelect}
                            selfIsFirstOption={true}
                            userGroups={{
                                subsetUserIds: participantUserIds,
                                defaultLabel: formatMessage({defaultMessage: 'NOT PARTICIPATING'}),
                                subsetLabel: formatMessage({defaultMessage: 'PARTICIPANTS'}),
                            }}
                        />
                    </span>
                </WithTooltip>
            ) : (
                <ProfileSelector
                    testId={'assignee-profile-selector'}
                    selectedUserId={checklistItem.assignee_id}
                    placeholder={formatMessage({defaultMessage: 'Assignee...'})}
                    enableEdit={editable}
                    getAllUsers={getAllUsersInTeam}
                    onSelectedChange={handleUserSelect}
                    selfIsFirstOption={true}
                    userGroups={{
                        subsetUserIds: participantUserIds,
                        defaultLabel: formatMessage({defaultMessage: 'NOT PARTICIPATING'}),
                        subsetLabel: formatMessage({defaultMessage: 'PARTICIPANTS'}),
                    }}
                    customControl={editable ? AssigneeOnlyCompleteControl : undefined}
                    customControlProps={editable ? {
                        showAssigneeOnlyComplete: true,
                        assigneeOnlyComplete: Boolean(checklistItem.assignee_only_complete),
                        onAssigneeOnlyCompleteChange: handleAssigneeOnlyCompleteChange,
                    } : undefined}
                    onOpenChange={onAssigneeMenuOpenChange}
                />
            )}
            <Divider/>
            <SectionLabel>{formatMessage({defaultMessage: 'ASSIGN TO A ROLE'})}</SectionLabel>
            <SelectWrapper data-testid='role-options'>
                <AssigneeSelect
                    aria-label={formatMessage({defaultMessage: 'Select role for assignee'})}
                    inputId='role-options'
                    options={roleOptions}
                    value={roleOptions.find((option) => option.value === displayRole)}
                    onChange={(option: RoleOption | null) => option && handleRoleRadioChange(option.value)}
                    isDisabled={!editable}
                    isSearchable={false}
                    styles={selectStyles}
                    classNamePrefix='assignee-role-select'
                    lang={locale}
                    dir={isRtl ? 'rtl' : 'ltr'}
                    components={{MenuPortal: LocalizedSelectMenuPortal}}
                    menuPortalTarget={document.body}
                    menuPosition='fixed'
                />
            </SelectWrapper>
            {displayRole === AssigneeTypePropertyUser && (
                <SelectWrapper data-testid='property-user-field-options'>
                    <AssigneeSelect
                        aria-label={formatMessage({defaultMessage: 'Select property field for assignee'})}
                        inputId='property-user-field-options'
                        options={[{value: '', label: formatMessage({defaultMessage: 'Select attribute...'})}, ...userPropertyFields.map((field) => ({value: field.id, label: field.name}))]}
                        value={userPropertyFields.some((field) => field.id === checklistItem.assignee_property_field_id) ? {value: checklistItem.assignee_property_field_id, label: userPropertyFields.find((field) => field.id === checklistItem.assignee_property_field_id)?.name ?? ''} : {value: '', label: formatMessage({defaultMessage: 'Select attribute...'})}}
                        onChange={(option: RoleOption | null) => option && handlePropertyUserFieldChange(option.value)}
                        isDisabled={!editable}
                        isSearchable={false}
                        styles={selectStyles}
                        classNamePrefix='assignee-role-select'
                        lang={locale}
                        dir={isRtl ? 'rtl' : 'ltr'}
                        components={{MenuPortal: LocalizedSelectMenuPortal}}
                        menuPortalTarget={document.body}
                        menuPosition='fixed'
                    />
                </SelectWrapper>
            )}
        </Container>
    );
};

const Container = styled.div`
    display: flex;
    flex-direction: column;
    gap: 4px;
`;

const DisabledReasonBanner = styled.div`
    margin: 0 8px 4px;
    padding-block: 6px;
    padding-inline: 8px;
    border-radius: 4px;
    background: rgba(var(--center-channel-color-rgb), 0.08);
    color: rgba(var(--center-channel-color-rgb), 0.72);
    font-size: 12px;
    line-height: 16px;
`;

const SectionLabel = styled.div`
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.02em;
    text-transform: uppercase;
    color: rgba(var(--center-channel-color-rgb), 0.56);
    padding-block: 4px 2px;
    padding-inline: 8px;
`;

const Divider = styled.div`
    height: 1px;
    background: rgba(var(--center-channel-color-rgb), 0.08);
    margin: 4px 0;
`;

const SelectWrapper = styled.div`
    padding-block: 2px 6px;
    padding-inline: 8px;
`;

const AssigneeSelect = styled(ReactSelect)`
    width: 100%;
`;

const assigneeSelectStyles = (isRtl: boolean): StylesConfig<RoleOption, false> => ({
    control: (provided, state) => ({
        ...provided,
        minHeight: '32px',
        borderColor: state.isFocused ? 'var(--button-bg)' : 'rgba(var(--center-channel-color-rgb), 0.16)',
        backgroundColor: 'var(--center-channel-bg)',
        boxShadow: state.isFocused ? '0 0 0 1px var(--button-bg)' : 'none',
        fontSize: '13px',
        cursor: 'pointer',
        ':hover': {borderColor: 'var(--button-bg)'},
    }),
    valueContainer: (provided) => ({...provided, paddingBlock: '0', paddingInline: '8px'}),
    indicatorSeparator: () => ({display: 'none'}),
    dropdownIndicator: (provided) => ({...provided, paddingBlock: '4px', paddingInline: '4px', color: 'rgba(var(--center-channel-color-rgb), 0.56)'}),
    menu: (provided) => ({...provided, backgroundColor: 'var(--center-channel-bg)', direction: isRtl ? 'rtl' : 'ltr'}),
    menuPortal: (provided) => ({...provided, fontFamily: '"Thmanyah Sans", sans-serif', direction: isRtl ? 'rtl' : 'ltr', zIndex: 9999}),
    option: (provided, state) => ({
        ...provided,
        backgroundColor: (() => {
            if (state.isSelected) {
                return 'rgba(var(--button-bg-rgb), 0.16)';
            }
            if (state.isFocused) {
                return 'rgba(var(--button-bg-rgb), 0.08)';
            }
            return 'var(--center-channel-bg)';
        })(),
        color: 'var(--center-channel-color)',
        cursor: 'pointer',
        ':active': {backgroundColor: 'rgba(var(--button-bg-rgb), 0.16)'},
    }),
    singleValue: (provided) => ({...provided, color: 'var(--center-channel-color)'}),
});

const CompactProfileSelector = styled(ProfileSelector)`
    .PlaybookRunProfileButton {
        height: 24px;
        padding-block: 2px;
        padding-inline: 2px 6px;
        background: rgba(var(--center-channel-color-rgb), 0.08);
        border-radius: 100px;

        .image {
            width: 20px;
            height: 20px;
        }

        .PlaybookRunProfile {
            font-size: 12px;
            font-weight: 400;
            line-height: 10px;
        }
    }
`;

const RoleBadge = styled.span`
    display: inline-flex;
    align-items: center;
    font-size: 11px;
    font-weight: 700;
    color: rgba(var(--button-bg-rgb), 1);
    background: rgba(var(--button-bg-rgb), 0.08);
    border-radius: 4px;
    padding-block: 2px;
    padding-inline: 6px;
    white-space: nowrap;
`;

export default AssigneeDropdown;
