import './tabler_icon.scss';

type Props = React.HTMLAttributes<HTMLElement> & {
    color?: string;
    size?: number | string;
    stroke?: number | string;
};

const icons = {
    'fa-upload': IconUpload,
    'icon-account-multiple-outline': IconUsers,
    'icon-account-outline': IconUser,
    'icon-account-plus-outline': IconUserPlus,
    'icon-alert-outline': IconAlertTriangle,
    'icon-archive-outline': IconArchive,
    'icon-arrow-back-ios': IconChevronLeft,
    'icon-arrow-collapse': IconArrowsMinimize,
    'icon-arrow-down': IconArrowDown,
    'icon-arrow-expand': IconArrowsMaximize,
    'icon-arrow-left': IconArrowLeft,
    'icon-arrow-right': IconArrowRight,
    'icon-arrow-up': IconArrowUp,
    'icon-bars': IconMenu2,
    'icon-book-lock-outline': IconBook2,
    'icon-book-outline': IconBook,
    'icon-calendar-outline': IconCalendar,
    'icon-cancel': IconBan,
    'icon-check': IconCheck,
    'icon-check-all': IconChecks,
    'icon-check-circle': IconCircleCheck,
    'icon-check-circle-outline': IconCircleCheck,
    'icon-chevron-down': IconChevronDown,
    'icon-chevron-left': IconChevronLeft,
    'icon-chevron-right': IconChevronRight,
    'icon-chevron-up': IconChevronUp,
    'icon-clock-outline': IconClock,
    'icon-close': IconX,
    'icon-close-circle': IconCircleX,
    'icon-content-copy': IconCopy,
    'icon-dots-vertical': IconDotsVertical,
    'icon-drag-vertical': IconGripVertical,
    'icon-exit-to-app': IconLogout,
    'icon-filter-variant': IconFilter,
    'icon-flag-outline': IconFlag,
    'icon-format-list-bulleted': IconList,
    'icon-globe': IconGlobe,
    'icon-information-outline': IconInfoCircle,
    'icon-lightning-bolt-outline': IconBolt,
    'icon-link-variant': IconLink,
    'icon-lock-outline': IconLock,
    'icon-pencil-outline': IconPencil,
    'icon-play-outline': IconPlayerPlay,
    'icon-plus': IconPlus,
    'icon-refresh': IconRefresh,
    'icon-send': IconSend,
    'icon-shield-alert-outline': IconShieldExclamation,
    'icon-slash-forward': IconSlash,
    'icon-source-branch': IconGitBranch,
    'icon-trash-can-outline': IconTrash,
    'icon-update': IconRefresh,
} as const;

const rtlMirroredIcons = new Set<keyof typeof icons>([
    'icon-arrow-back-ios',
    'icon-arrow-left',
    'icon-arrow-right',
    'icon-chevron-left',
    'icon-chevron-right',
    'icon-exit-to-app',
    'icon-send',
]);

// eslint-disable-next-line react/prop-types
const TablerIcon = React.forwardRef<HTMLElement, Props>(({className = '', size, style, 'aria-label': ariaLabel, ...props}, ref) => {
    const iconClass = className.split(/\s+/).find((name) => name in icons) as keyof typeof icons | undefined;
    if (!iconClass) {
        return (
            <i
                ref={ref}
                className={className}
                aria-label={ariaLabel}
                {...props}
                style={style}
            />
        );
    }

    const Component = icons[iconClass];
    const resolvedClassName = rtlMirroredIcons.has(iconClass) ? `${className} tabler-icon--rtl-mirror` : className;
    let resolvedSize = size ?? 18;
    if (size === undefined && className.includes('icon-12')) {
        resolvedSize = 12;
    } else if (size === undefined && className.includes('icon-16')) {
        resolvedSize = 16;
    }
    return (
        <Component
            ref={ref as React.Ref<SVGSVGElement>}
            className={resolvedClassName}
            size={resolvedSize}
            aria-label={ariaLabel}
            aria-hidden={ariaLabel ? undefined : true}
            {...props as React.ComponentPropsWithoutRef<'svg'>}
            style={{...style, fill: 'none'}}
        />
    );
});

TablerIcon.displayName = 'TablerIcon';

export default TablerIcon;
