import React from 'react';
import {useIntl} from 'react-intl';
import styled from 'styled-components';

import {workspaceTypography} from 'src/styles/workspace';
import {isRtlLocale} from 'src/utils';

const LocalizedPost = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>((props, ref) => {
    const {locale = 'en'} = useIntl();
    return (
        <div
            {...props}
            ref={ref}
            lang={locale}
            dir={isRtlLocale(locale) ? 'rtl' : 'ltr'}
        />
    );
});
LocalizedPost.displayName = 'LocalizedPost';

export const CustomPostContainer = styled(LocalizedPost)`
    ${workspaceTypography}
    display: flex;
    width: 640px;
    max-width: 100%;
    min-width: 0;
    box-sizing: border-box;
    container-type: inline-size;
    flex-direction: row;
    border: 1px solid rgba(var(--center-channel-color-rgb), 0.16);
    border-radius: 4px;
    box-shadow: 0 2px 3px rgba(0 0 0 / 0.08);
`;

export const CustomPostContent = styled.div`
    display: flex;
    flex-direction: column;
    flex: 1 1 0;
    box-sizing: border-box;
    min-width: 0;
    overflow-wrap: anywhere;
    padding-block: 12px;
    padding-inline: 12px;
    padding-inline-start: 16px;
`;

export const CustomPostHeader = styled.div`
    font-size: 16px;
    font-weight: 700;
    line-height: 24px;
`;

export const CustomPostButtonRow = styled.div`
    display: flex;
    flex-flow: row wrap;
    gap: 8px;
    padding-block-start: 12px;

    && > button {
        min-width: 0;
        height: auto;
        min-height: 36px;
        flex: 1 1 160px;
        padding-block: 8px;
        padding-inline: 12px;
        margin: 0;
        line-height: 1.5;
        white-space: normal;
        overflow-wrap: anywhere;
    }
`;
