import React from 'react';
import ReactDOM from 'react-dom';
import {useIntl} from 'react-intl';
import styled from 'styled-components';

import {isRtlLocale} from 'src/utils';

const placeholderID = 'playbooks-rhs-title-placeholder';

const PlaceholderContainer = styled.div`
    width: 100%;
    height: 100%;
`;

export const RHSTitlePlaceholder = () => {
    return (
        <PlaceholderContainer
            id={placeholderID}
        />
    );
};

export const RHSTitleRemoteRender = (props: {children: React.ReactNode}) => {
    const {locale} = useIntl();
    const container = document.getElementById(placeholderID);
    if (!container) {
        return null;
    }

    return ReactDOM.createPortal(
        <TitleDirection
            lang={locale}
            dir={isRtlLocale(locale) ? 'rtl' : 'ltr'}
        >
            {props.children}
        </TitleDirection>,
        container,
    );
};

const TitleDirection = styled.div`
    display: flex;
    height: 100%;
    align-items: center;
    font-family: var(--workspace-font-family, "Thmanyah Sans", sans-serif);
`;
