import React from 'react';
import {useIntl} from 'react-intl';
import {OptionTypeBase, components} from 'react-select';
import {MenuPortalProps} from 'react-select/src/components/Menu';
import styled from 'styled-components';

import {workspaceTypography} from 'src/styles/workspace';
import {isRtlLocale} from 'src/utils';

// React Select portals leave the plugin DOM tree, so carry locale and typography with the menu.
export default function LocalizedSelectMenuPortal<Option extends OptionTypeBase, IsMulti extends boolean>(props: MenuPortalProps<Option, IsMulti>) {
    const {locale = 'en'} = useIntl();
    return (
        <components.MenuPortal {...props}>
            <MenuSurface
                lang={locale}
                dir={isRtlLocale(locale) ? 'rtl' : 'ltr'}
            >
                {props.children}
            </MenuSurface>
        </components.MenuPortal>
    );
}

const MenuSurface = styled.div`
    ${workspaceTypography}
`;
