import React from 'react';
import {MenuListComponentProps, OptionTypeBase, components} from 'react-select';

// Keep react-select's scroll container, keyboard focus and RTL behavior together.
const MenuList = <T extends OptionTypeBase>(props: MenuListComponentProps<T, boolean>) => (
    <components.MenuList {...props}>
        {props.children}
    </components.MenuList>
);

export default MenuList;
