import {getCurrentChannel} from 'mattermost-redux/selectors/entities/channels';

import {matchPath} from 'react-router-dom';

import {Store} from 'src/types/store';

import {hasViewedByChannelID} from 'src/selectors';
import {fetchChannelActions, fetchCheckAndSendMessageOnJoin} from 'src/client';
import {setHasViewedChannel} from 'src/actions';
import {ChannelActionType, ChannelTriggerType} from 'src/types/channel_actions';

export function makeWelcomeMessagePoster(store: Store): () => Promise<void> {
    let currentChannelId = '';
    const pendingChannels = new Set<string>();
    const retryAfterByChannel = new Map<string, number>();

    return async () => {
        const state = store.getState();
        const currentChannel = getCurrentChannel(state);
        const url = new URL(window.location.href);
        const isInChannel = matchPath(url.pathname, {path: '/:team/:path(channels|messages)/:identifier/:postid?'});

        // Wait for a valid team and channel before doing anything.
        if (!isInChannel || !currentChannel) {
            return;
        }

        const channelId = currentChannel.id;

        // Store listeners run for every action, including while requests are pending.
        if (channelId === currentChannelId || pendingChannels.has(channelId) ||
            Date.now() < (retryAfterByChannel.get(channelId) ?? 0)) {
            return;
        }

        // if the user has already viewed the channel,
        // there's no need to fetch actions again
        if (hasViewedByChannelID(state)[channelId]) {
            currentChannelId = channelId;
            return;
        }

        pendingChannels.add(channelId);
        try {
            const actions = await fetchChannelActions(channelId, ChannelTriggerType.NewMemberJoins);

            // Do not initiate a welcome message for a channel the user has left.
            if (getCurrentChannel(store.getState())?.id !== channelId) {
                return;
            }

            const welcomeAction = actions.find((action) =>
                action.trigger_type === ChannelTriggerType.NewMemberJoins && action.action_type === ChannelActionType.WelcomeMessage
            );
            if (welcomeAction?.enabled) {
                const hasViewed = await fetchCheckAndSendMessageOnJoin(channelId);
                if (hasViewed) {
                    store.dispatch(setHasViewedChannel(channelId));
                }
            }

            if (getCurrentChannel(store.getState())?.id === channelId) {
                currentChannelId = channelId;
            }
            retryAfterByChannel.delete(channelId);
        } catch (error) {
            // Subscribers do not await this promise. Handle failures here and avoid
            // retrying on every store update while the network is unavailable.
            retryAfterByChannel.set(channelId, Date.now() + 30000);
            console.error('Unable to check the playbook welcome message for this channel.', error); // eslint-disable-line no-console
        } finally {
            pendingChannels.delete(channelId);
        }
    };
}
