import {useEffect} from 'react';

import {loadRolesIfNeeded} from 'mattermost-redux/actions/roles';

import {useAppDispatch, useAppSelector} from 'src/hooks/redux';

import {globalSettings} from 'src/selectors';
import {actionSetGlobalSettings} from 'src/actions';
import {fetchGlobalSettings, notifyConnect} from 'src/client';
import {PlaybookRole} from 'src/types/permissions';

// This component is meant to be registered as RootComponent.
// It will be registered at initialize and "rendered" at login.
const LoginHook = () => {
    const dispatch = useAppDispatch();
    const hasGlobalSettings = useAppSelector((state) => Boolean(globalSettings(state)));
    useEffect(() => {
        if (hasGlobalSettings) {
            return undefined;
        }

        let active = true;
        const fetchAndStoreSettings = async () => {
            try {
                const settings = await fetchGlobalSettings();
                if (active) {
                    dispatch(actionSetGlobalSettings(settings));
                }
            } catch (error) {
                console.error('Unable to load playbook global settings.', error); // eslint-disable-line no-console
            }
        };
        fetchAndStoreSettings();

        return () => {
            active = false;
        };
    }, [dispatch, hasGlobalSettings]);

    useEffect(() => {
        // Grab roles
        dispatch(loadRolesIfNeeded([PlaybookRole.Member, PlaybookRole.Admin]));

        // Fire the first connect bot event.
        notifyConnect().catch((error) => {
            console.error('Unable to notify the playbook bot of this connection.', error); // eslint-disable-line no-console
        });
    }, [dispatch]);

    return null;
};

export default LoginHook;
