import {css} from 'styled-components';

// Scope host typography to plugin surfaces; icon fonts retain their own family.
export const workspaceTypography = css`
    --workspace-font-family: "Thmanyah Sans", sans-serif;

    color: var(--center-channel-color);
    font-family: var(--workspace-font-family, "Thmanyah Sans", sans-serif);
    font-size: 14px;
    font-weight: 400;
    line-height: 1.5;
    text-align: start;

    & :where(h1, h2, h3, h4, h5, h6, button, input, textarea, select) {
        font-family: inherit;
    }

    & :where(input, textarea) {
        caret-color: var(--button-bg);
    }

    & :where(button, a, input, textarea, select, [tabindex]):focus-visible {
        outline: 2px solid var(--button-bg);
        outline-offset: 2px;
    }

    ::selection {
        background: rgba(var(--button-bg-rgb), 0.16);
        color: var(--center-channel-color);
    }
`;
