import React from 'react';
import {HashLink as Link} from 'react-router-hash-link';
import styled, {css} from 'styled-components';

export const Section = styled.section`
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    padding-block: 24px;
    padding-inline: 0;
    border-bottom: 1px solid rgba(var(--center-channel-color-rgb), 0.08);
`;

type LinkURL = {to: string, name: string};
type LinkHandler = {onClick: () => void, name: string};

function isLinkURL(link: LinkURL | LinkHandler): link is LinkURL {
    return 'to' in link;
}

interface SectionHeaderProps {
    title: string;
    link?: LinkURL | LinkHandler;
    children?: React.ReactNode;
}

export const SectionHeader = ({title, link, children}: SectionHeaderProps) => (
    <SectionHeaderContainer>
        <SectionTitle>{title}</SectionTitle>
        {children}
        {link && <SectionLink link={link}/>}
    </SectionHeaderContainer>
);

const SectionLink = ({link}: {link: LinkURL | LinkHandler}) => {
    if (isLinkURL(link)) {
        return (
            <StyledLink to={link.to}>
                {link.name}
            </StyledLink>
        );
    }

    return (
        <StyledSpan onClick={link.onClick}>
            {link.name}
        </StyledSpan>
    );
};

const SectionHeaderContainer = styled.div`
    display: flex;
    box-sizing: border-box;
    min-width: 0;
    flex-direction: row;
    justify-content: space-between;
    padding-block: 0;
    padding-inline: 24px;
    margin-bottom: 8px;
`;

const SectionTitle = styled.div`
    color: rgba(var(--center-channel-color-rgb), 0.72);
    font-family: var(--workspace-font-family, "Thmanyah Sans", sans-serif);
    font-size: 12px;
    font-style: normal;
    font-weight: 700;
    text-transform: uppercase;
`;

const LinkStyle = css`
    color: var(--button-bg);
    cursor: pointer;
    font-size: 12px;
    font-weight: 700;
    opacity: 0;
    transition: opacity .2s;

    &:hover{
        text-decoration: underline;
    }
    ${Section}:hover & {
        opacity: 1;
    }
`;

const StyledLink = styled(Link)`
    ${LinkStyle}
`;

const StyledSpan = styled.span`
    ${LinkStyle}
`;
