export enum ButtonsFormat {

    // All buttons are shown regardless of their state if they're editable;
    // owner name is shown completely
    Long = 'long',

    // Only buttons with a value are shown;
    // owner name is shown completely
    Mixed = 'mixed',

    // Only buttons with a value are shown;
    // owner name is not shown when other buttons have a value
    Short = 'short',
}

interface ChecklistItemProps {
    checklistItem: ChecklistItemType;
    checklistNum: number;
    itemNum: number;
    playbookRunId?: string;
    playbookId?: string;
    teamId?: string;
    channelId?: string;
    timelineEvents?: TimelineEvent[];
    onChange?: (item: ChecklistItemState, requirementValues?: Record<string, string>) => ReturnType<typeof setChecklistItemState> | undefined;
    draggableProvided?: DraggableProvided;
    dragging: boolean;
    readOnly: boolean;
    dragDisabled?: boolean;
    collapsibleDescription: boolean;
    descriptionCollapsedByDefault?: boolean;
    newItem: boolean;
    cancelAddingItem?: () => void;
    onUpdateChecklistItem?: (newItem: ChecklistItemType) => void;
    onAddChecklistItem?: (newItem: ChecklistItemType) => void;
    onDuplicateChecklistItem?: () => void;
    onDeleteChecklistItem?: () => void;
    buttonsFormat?: ButtonsFormat;
    participantUserIds: string[];
    onReadOnlyInteract?: () => void;
    onAddConditional?: () => void;
    onRemoveFromCondition?: () => void;
    onAssignToCondition?: (conditionId: string) => void;
    availableConditions?: Condition[];
    conditions?: Condition[];
    propertyFields?: PropertyField[];
    propertyValues?: PropertyValue[];
    onEditingChange?: (isEditing: boolean) => void;
    hasCondition?: boolean;
    conditionHeader?: React.ReactNode;
    onSaveAndAddNew?: () => void;
    isChannelChecklist?: boolean;
    runOwnerId?: string;
    runCreatorId?: string;
    bulkEditMode?: boolean;
    isSelected?: boolean;
    onItemSelect?: () => void;
}

const itemHasAssignee = (assigneeId?: string, type?: string) =>
    Boolean(assigneeId) || isRoleBasedAssigneeType(type || '');

export const ChecklistItem = (props: ChecklistItemProps): React.ReactElement => {
    const {formatMessage, locale} = useIntl();
    const toaster = useToaster();
    const currentUserId = useAppSelector(getCurrentUserId);
    const isPlaybookEditor = !props.playbookRunId;
    const betaFeaturesEnabled = useAppSelector(selectTaskRequirementsEnabled);
    const isMounted = useRef(true);
    useEffect(() => {
        return () => {
            isMounted.current = false;
        };
    }, []);

    const [showDescription, setShowDescription] = useState(!props.descriptionCollapsedByDefault);

    const getConditionTooltip = (item: ChecklistItemType): string => {
        if (item.condition_action === 'shown_because_modified') {
            return formatMessage({
                defaultMessage: 'Condition no longer met, but task shown because it was modified',
            });
        }

        // Get the reason - either from the item or format the condition expression
        let reason = item.condition_reason;
        if (!reason && item.condition_id && props.conditions && props.propertyFields) {
            const condition = props.conditions.find((c) => c.id === item.condition_id);
            if (condition) {
                reason = formatConditionExpr(condition.condition_expr, props.propertyFields);
            }
        }

        if (isPlaybookEditor) {
            return formatMessage(
                {defaultMessage: 'Shown when {reason}'},
                {reason},
            );
        }

        return formatMessage(
            {defaultMessage: 'Shown because {reason}'},
            {reason},
        );
    };
    const [isEditing, setIsEditing] = useState(props.newItem);
    const [isHoverMenuItemOpen, setIsHoverMenuItemOpen] = useState(false);
    const [titleValue, setTitleValue] = useState(localizeStoredPresetValue(props.checklistItem.title, locale));
    const [descValue, setDescValue] = useState(localizeStoredPresetValue(props.checklistItem.description, locale));
    const [command, setCommand] = useState(localizeStoredPresetValue(props.checklistItem.command, locale));
    const [taskActions, setTaskActions] = useState(props.checklistItem.task_actions);
    const [assigneeID, setAssigneeID] = useState(props.checklistItem.assignee_id);
    const [assigneeType, setAssigneeType] = useState(props.checklistItem.assignee_type || '');
    const [assigneePropertyFieldID, setAssigneePropertyFieldID] = useState(props.checklistItem.assignee_property_field_id || '');
    const [assigneeOnlyComplete, setAssigneeOnlyComplete] = useState(Boolean(props.checklistItem.assignee_only_complete));
    const [dueDate, setDueDate] = useState(props.checklistItem.due_date);
    const [showAddRequirementModal, setShowAddRequirementModal] = useState(false);
    const [showFillRequirementsModal, setShowFillRequirementsModal] = useState(false);
    const [fillRequirementsEditMode, setFillRequirementsEditMode] = useState(false);
    const {updateRunTaskActions} = useUpdateRunItemTaskActions(props.playbookRunId);

    const requirements = props.checklistItem.requirements || [];

    const userPropertyFields = useMemo(
        () => props.propertyFields?.filter((f) => f.type === PropertyFieldType.User) ?? [],
        [props.propertyFields],
    );

    const roleOptions = useMemo(() => {
        const opts = [
            {value: `${EXTRA_OPTION_PREFIX_ROLE}owner`, label: formatMessage({defaultMessage: 'Run Owner'})},
            {value: `${EXTRA_OPTION_PREFIX_ROLE}creator`, label: formatMessage({defaultMessage: 'Run Creator'})},
        ];
        for (const f of userPropertyFields) {
            opts.push({
                value: `${EXTRA_OPTION_PREFIX_PROPERTY_USER}${f.id}`,
                label: formatMessage({defaultMessage: 'Run {name}'}, {name: f.name}),
            });
        }
        return opts;
    }, [formatMessage, userPropertyFields]);

    // Merge local state into the checklistItem so child components see changes
    // immediately rather than waiting for a WebSocket round-trip or prop update.
    const localChecklistItem = useMemo(() => ({
        ...props.checklistItem,
        assignee_id: assigneeID,
        assignee_type: assigneeType,
        assignee_property_field_id: assigneePropertyFieldID,
        assignee_only_complete: assigneeOnlyComplete,
    }), [props.checklistItem, assigneeID, assigneeType, assigneePropertyFieldID, assigneeOnlyComplete]);

    // Notify parent when editing state changes
    useUpdateEffect(() => {
        props.onEditingChange?.(isEditing);
    }, [isEditing]);

    const toggleDescription = () => setShowDescription(!showDescription);

    const isSkipped = () => {
        return props.checklistItem.state === ChecklistItemState.Skip;
    };

    useUpdateEffect(() => {
        setTitleValue(localizeStoredPresetValue(props.checklistItem.title, locale));
    }, [props.checklistItem.title, locale]);

    useUpdateEffect(() => {
        setDescValue(localizeStoredPresetValue(props.checklistItem.description, locale));
    }, [props.checklistItem.description, locale]);

    useUpdateEffect(() => {
        setCommand(localizeStoredPresetValue(props.checklistItem.command, locale));
    }, [props.checklistItem.command, locale]);

    useUpdateEffect(() => {
        setAssigneeID(props.checklistItem.assignee_id);
    }, [props.checklistItem.assignee_id]);

    useUpdateEffect(() => {
        setAssigneeType(props.checklistItem.assignee_type || '');
    }, [props.checklistItem.assignee_type]);

    useUpdateEffect(() => {
        setAssigneePropertyFieldID(props.checklistItem.assignee_property_field_id || '');
    }, [props.checklistItem.assignee_property_field_id]);

    useUpdateEffect(() => {
        setAssigneeOnlyComplete(Boolean(props.checklistItem.assignee_only_complete));
    }, [props.checklistItem.assignee_only_complete]);

    useUpdateEffect(() => {
        setDueDate(props.checklistItem.due_date);
    }, [props.checklistItem.due_date]);

    useUpdateEffect(() => {
        setTaskActions(taskActions);
    }, [props.checklistItem.task_actions]);

    const assigneeCallSeqRef = useRef(0);
    const assigneeStateRef = useRef({id: assigneeID, type: assigneeType, fieldID: assigneePropertyFieldID});
    const assigneeOnlyCompleteRef = useRef(assigneeOnlyComplete);
    const checklistItemRef = useRef(props.checklistItem);

    useEffect(() => {
        assigneeStateRef.current = {id: assigneeID, type: assigneeType, fieldID: assigneePropertyFieldID};
    }, [assigneeID, assigneeType, assigneePropertyFieldID]);

    useEffect(() => {
        assigneeOnlyCompleteRef.current = assigneeOnlyComplete;
    }, [assigneeOnlyComplete]);

    useEffect(() => {
        checklistItemRef.current = props.checklistItem;
    }, [props.checklistItem]);

    const discardPendingLock = useCallback(() => {
        const {id, type} = assigneeStateRef.current;
        if (!itemHasAssignee(id, type) && assigneeOnlyCompleteRef.current) {
            assigneeOnlyCompleteRef.current = false;
            setAssigneeOnlyComplete(false);
        }
    }, []);

    const onAssigneeMenuOpenChange = useCallback((isOpen: boolean) => {
        if (!isOpen) {
            discardPendingLock();
        }
    }, [discardPendingLock]);

    const handleAssigneeDropdownChange = useCallback(async (updatedItem: ChecklistItemType) => {
        const seq = ++assigneeCallSeqRef.current;
        const previousAssigneeOnlyComplete = assigneeOnlyCompleteRef.current;
        const assigneeFieldsChanged =
            (updatedItem.assignee_id || '') !== assigneeStateRef.current.id ||
            (updatedItem.assignee_type || '') !== assigneeStateRef.current.type ||
            (updatedItem.assignee_property_field_id || '') !== assigneeStateRef.current.fieldID;
        const updatedHasAssignee = itemHasAssignee(updatedItem.assignee_id, updatedItem.assignee_type);
        const localLock = Boolean(updatedItem.assignee_only_complete) && (updatedHasAssignee || !assigneeFieldsChanged);
        const persistableLock = Boolean(updatedItem.assignee_only_complete) && updatedHasAssignee;
        const persistedLock = Boolean(checklistItemRef.current.assignee_only_complete);
        const lockChanged = persistableLock !== persistedLock;

        assigneeStateRef.current = {id: updatedItem.assignee_id || '', type: updatedItem.assignee_type || '', fieldID: updatedItem.assignee_property_field_id || ''};
        const rollback = () => {
            if (isMounted.current && assigneeCallSeqRef.current === seq) {
                // Use latest props so a server push during the mutation isn't lost on rollback.
                const latest = checklistItemRef.current;
                assigneeStateRef.current = {id: latest.assignee_id || '', type: latest.assignee_type || '', fieldID: latest.assignee_property_field_id || ''};
                setAssigneeID(latest.assignee_id || '');
                setAssigneeType(latest.assignee_type || '');
                setAssigneePropertyFieldID(latest.assignee_property_field_id || '');
                assigneeOnlyCompleteRef.current = Boolean(latest.assignee_only_complete);
                setAssigneeOnlyComplete(Boolean(latest.assignee_only_complete));
            }
        };
        const handleError = (hasError: boolean) => {
            if (hasError && isMounted.current && assigneeCallSeqRef.current === seq) {
                rollback();
                toaster.add({
                    content: formatMessage({defaultMessage: 'Failed to update assignee.'}),
                    toastStyle: ToastStyle.Failure,
                });
            }
        };
        setAssigneeID(updatedItem.assignee_id || '');
        setAssigneeType(updatedItem.assignee_type || '');
        setAssigneePropertyFieldID(updatedItem.assignee_property_field_id || '');
        assigneeOnlyCompleteRef.current = localLock;
        setAssigneeOnlyComplete(localLock);
        if (props.newItem) {
            return;
        }
        if (props.playbookRunId) {
            try {
                if (assigneeFieldsChanged) {
                    let response;
                    if (updatedItem.assignee_type === AssigneeTypeOwner || updatedItem.assignee_type === AssigneeTypeCreator) {
                        response = await setRoleAssignee(props.playbookRunId, props.checklistNum, props.itemNum, updatedItem.assignee_type);
                    } else if (updatedItem.assignee_type === AssigneeTypePropertyUser && updatedItem.assignee_property_field_id) {
                        response = await setPropertyUserAssignee(props.playbookRunId, props.checklistNum, props.itemNum, updatedItem.assignee_property_field_id);
                    } else {
                        response = await setAssignee(props.playbookRunId, props.checklistNum, props.itemNum, updatedItem.assignee_id || '');
                    }
                    handleError(Boolean(response.error));
                    if (response.error) {
                        return;
                    }
                }

                if (lockChanged) {
                    const response = await clientSetAssigneeOnlyComplete(
                        props.playbookRunId,
                        props.checklistNum,
                        props.itemNum,
                        persistableLock,
                    );
                    if (response.error && isMounted.current && assigneeCallSeqRef.current === seq) {
                        assigneeOnlyCompleteRef.current = previousAssigneeOnlyComplete;
                        setAssigneeOnlyComplete(previousAssigneeOnlyComplete);
                        toaster.add({
                            content: formatMessage({defaultMessage: 'Failed to update task lock.'}),
                            toastStyle: ToastStyle.Failure,
                        });
                    }
                }
            } catch {
                handleError(true);
            }
        } else if (assigneeFieldsChanged || persistableLock !== persistedLock) {
            props.onUpdateChecklistItem?.({
                ...updatedItem,
                assignee_only_complete: persistableLock,
            });
        }
    }, [props.playbookRunId, props.checklistNum, props.itemNum, props.newItem, props.onUpdateChecklistItem, formatMessage, toaster]);

    const onAssigneeChange = useCallback((user?: UserProfile) => {
        handleAssigneeDropdownChange({
            ...props.checklistItem,
            assignee_id: user?.id || '',
            assignee_type: '',
            assignee_property_field_id: '',
            assignee_only_complete: user?.id ? assigneeOnlyCompleteRef.current : false,
        });
    }, [props.checklistItem, handleAssigneeDropdownChange]);

    const onExtraOptionSelected = useCallback(async (value: string) => {
        const updatedItem = {
            ...props.checklistItem,
            assignee_only_complete: assigneeOnlyCompleteRef.current,
        };
        updatedItem.assignee_id = '';

        if (value.startsWith(EXTRA_OPTION_PREFIX_ROLE)) {
            updatedItem.assignee_type = value.slice(EXTRA_OPTION_PREFIX_ROLE.length);
            updatedItem.assignee_property_field_id = '';
        } else if (value.startsWith(EXTRA_OPTION_PREFIX_PROPERTY_USER)) {
            updatedItem.assignee_type = AssigneeTypePropertyUser;
            updatedItem.assignee_property_field_id = value.slice(EXTRA_OPTION_PREFIX_PROPERTY_USER.length);
        }

        await handleAssigneeDropdownChange(updatedItem);
    }, [props.checklistItem, handleAssigneeDropdownChange]);

    const onAssigneeOnlyCompleteChange = useCallback(async (value: boolean) => {
        const previous = assigneeOnlyCompleteRef.current;
        assigneeOnlyCompleteRef.current = value;
        setAssigneeOnlyComplete(value);

        const hasAssigneeNow = itemHasAssignee(assigneeID, assigneeType);
        if (value && !hasAssigneeNow) {
            // Keep the lock pending until an assignee is chosen or the picker closes.
            return;
        }
        if (!value && !props.checklistItem.assignee_only_complete) {
            return;
        }
        if (props.newItem) {
            return;
        }
        if (props.playbookRunId) {
            const response = await clientSetAssigneeOnlyComplete(props.playbookRunId, props.checklistNum, props.itemNum, value);
            if (response.error && isMounted.current) {
                assigneeOnlyCompleteRef.current = previous;
                setAssigneeOnlyComplete(previous);
                toaster.add({
                    content: formatMessage({defaultMessage: 'Failed to update task lock.'}),
                    toastStyle: ToastStyle.Failure,
                });
            }
        } else {
            props.onUpdateChecklistItem?.({
                ...props.checklistItem,
                assignee_id: assigneeID,
                assignee_type: assigneeType,
                assignee_property_field_id: assigneePropertyFieldID,
                assignee_only_complete: value,
            });
        }
    }, [
        assigneeID,
        assigneeType,
        assigneePropertyFieldID,
        props.newItem,
        props.playbookRunId,
        props.checklistNum,
        props.itemNum,
        props.checklistItem,
        props.onUpdateChecklistItem,
        formatMessage,
        toaster,
    ]);

    const onDueDateChange = async (value?: DateTimeOption | undefined | null) => {
        let timestamp = 0;
        if (value?.value) {
            timestamp = value?.value.toMillis();
        }
        setDueDate(timestamp);
        if (props.newItem) {
            return;
        }
        if (props.playbookRunId) {
            const response = await clientSetDueDate(props.playbookRunId, props.checklistNum, props.itemNum, timestamp);
            if (response.error) {
                console.log(response.error); // eslint-disable-line no-console
            }
        } else {
            const newItem = {...props.checklistItem};
            newItem.due_date = timestamp;
            props.onUpdateChecklistItem?.(newItem);
        }
    };

    const onCommandChange = async (newCommand: string) => {
        setCommand(newCommand);
        if (props.newItem) {
            return;
        }
        if (props.playbookRunId) {
            clientSetChecklistItemCommand(props.playbookRunId, props.checklistNum, props.itemNum, newCommand);
        } else {
            const newItem = {...props.checklistItem};
            newItem.command = newCommand;
            props.onUpdateChecklistItem?.(newItem);
        }
    };

    const onTaskActionsChange = async (newTaskActions: TaskActionType[]) => {
        setTaskActions(newTaskActions);
        if (props.newItem) {
            return;
        }
        if (props.playbookRunId) {
            updateRunTaskActions(props.checklistNum, props.itemNum, newTaskActions);
        } else {
            const newItem = {...props.checklistItem};
            newItem.task_actions = newTaskActions;

            // Requirements and mark-as-done message triggers are mutually exclusive.
            if (haveAtleastOneEnabledAction(newTaskActions) && (newItem.requirements?.length || 0) > 0) {
                newItem.requirements = [];
            }
            props.onUpdateChecklistItem?.(newItem);
        }
    };

    const hasRoleAssignee = isRoleBasedAssigneeType(assigneeType);

    // In a run, locked tasks with an assignee may only be reassigned by the assignee or run owner.
    const hasAssignee = Boolean(assigneeID) || hasRoleAssignee;
    const isLockedToAssignee = Boolean(assigneeOnlyComplete && hasAssignee);
    const canChangeAssignee = !props.playbookRunId || !isLockedToAssignee ||
        currentUserId === props.runOwnerId ||
        Boolean(assigneeID && assigneeID === currentUserId);
    const assigneeDisabledReason = props.playbookRunId && isLockedToAssignee && !canChangeAssignee ? formatMessage({defaultMessage: 'Only the assignee or run owner can change the assignee'}) : undefined;

    // Renders the assignee editor above the toolbar — only when actively editing.
    // Kept separate from renderAssignTo so the toolbar Row remains unaffected.
    const renderAssigneeEditor = (): React.ReactNode => {
        return (
            <AssigneeEditorPanel>
                <AssigneeDropdown
                    checklistItem={localChecklistItem}
                    editable={canChangeAssignee}
                    disabledReason={assigneeDisabledReason}
                    onChanged={handleAssigneeDropdownChange}
                    onAssigneeMenuOpenChange={onAssigneeMenuOpenChange}
                    participantUserIds={props.participantUserIds}
                    runOwnerUserId={props.runOwnerId}
                    runCreatorUserId={props.runCreatorId}
                    mode={props.playbookRunId ? 'run' : 'template'}
                    propertyFields={props.propertyFields}
                />
            </AssigneeEditorPanel>
        );
    };

    const renderAssignTo = (): null | React.ReactNode => {
        if (isEditing) {
            return null;
        }

        if (!assigneeID && !hasRoleAssignee) {
            // hide when nothing is set
            return null;
        }

        return (
            <AssignTo
                participantUserIds={props.participantUserIds}
                assignee_id={assigneeID || ''}
                assignee_type={assigneeType}
                assignee_property_field_id={assigneePropertyFieldID}
                assignee_only_complete={assigneeOnlyComplete}
                editable={canChangeAssignee && !props.readOnly && !isSkipped()}
                disabledReason={assigneeDisabledReason}
                onSelectedChange={onAssigneeChange}
                onExtraOptionSelected={onExtraOptionSelected}
                onAssigneeOnlyCompleteChange={canChangeAssignee ? onAssigneeOnlyCompleteChange : undefined}
                onOpenChange={onAssigneeMenuOpenChange}
                roleOptions={roleOptions}
                propertyFields={props.propertyFields}
                propertyValues={props.propertyValues}
                runOwnerUserId={props.runOwnerId}
                runCreatorUserId={props.runCreatorId}
                mode={props.playbookRunId ? 'run' : 'template'}
                placement={'bottom-start'}
                isEditing={false}
                teamId={props.teamId}
                channelId={props.channelId}
            />
        );
    };

    const renderCommand = (): null | React.ReactNode => {
        if (!isEditing && !command) {
            // when not editing, hide when not set
            return null;
        }
        return (
            <Command
                checklistNum={props.checklistNum}
                command={command}
                command_last_run={props.checklistItem.command_last_run}
                disabled={!isEditing && (props.readOnly || isSkipped())}
                itemNum={props.itemNum}
                playbookRunId={props.playbookRunId}
                isEditing={isEditing}
                onChangeCommand={onCommandChange}
            />
        );
    };

    const renderDueDate = (): null | React.ReactNode => {
        const isTaskFinishedOrSkipped = props.checklistItem.state === ChecklistItemState.Closed || isSkipped();

        if (!isEditing && !dueDate) {
            // when not editing, hide when not set
            return null;
        }

        return (
            <DueDateButton
                editable={isEditing || (!props.readOnly && !isSkipped())}
                date={dueDate}
                ignoreOverdue={isTaskFinishedOrSkipped}
                mode={props.playbookRunId ? Mode.DateTimeValue : Mode.DurationValue}
                onSelectedChange={onDueDateChange}
                placement={'bottom-start'}
                isEditing={isEditing}
            />
        );
    };

    const renderTaskActions = (): null | React.ReactNode => {
        const hasEnabledActions = haveAtleastOneEnabledAction(taskActions);
        if (!isEditing && !hasEnabledActions) {
            // when not editing, hide when not set
            return null;
        }

        const taskActionsDisabledReason = isPlaybookEditor && betaFeaturesEnabled && requirements.length > 0 ? formatMessage({defaultMessage: 'Remove task requirements before adding a message trigger.'}) : undefined;

        return (
            <TaskActions
                editable={isEditing || (!props.readOnly && !isSkipped())}
                taskActions={taskActions}
                onTaskActionsChange={onTaskActionsChange}
                isEditing={isEditing}
                disabledReason={taskActionsDisabledReason}
            />
        );
    };

    const renderCheckedChip = (): null | React.ReactNode => {
        if (!shouldShowCheckedChip(props.checklistItem)) {
            return null;
        }
        return (
            <CheckedChip
                item={props.checklistItem}
                timelineEvents={props.timelineEvents}
                compact={true}
            />
        );
    };

    const handleSave = () => {
        discardPendingLock();
        setIsEditing(false);
        const finalTitle = titleValue.trim() || formatMessage({defaultMessage: 'Untitled task'});
        if (props.newItem) {
            props.cancelAddingItem?.();
            const newItem = {
                title: finalTitle,
                command,
                description: descValue,
                state: ChecklistItemState.Open,
                command_last_run: 0,
                due_date: dueDate,
                assignee_id: assigneeID,
                assignee_type: assigneeType,
                assignee_only_complete: Boolean(assigneeOnlyCompleteRef.current && itemHasAssignee(assigneeID, assigneeType)),
                task_actions: taskActions,
                requirements: props.checklistItem.requirements || [],
                state_modified: 0,
                assignee_modified: 0,
                condition_id: '',
                condition_action: '',
                condition_reason: '',
                assignee_property_field_id: assigneePropertyFieldID,
            };
            if (props.playbookRunId) {
                clientAddChecklistItem(props.playbookRunId, props.checklistNum, newItem);
            } else {
                props.onAddChecklistItem?.(newItem);
            }
        } else if (props.playbookRunId) {
            clientEditChecklistItem(props.playbookRunId, props.checklistNum, props.itemNum, {
                title: finalTitle,
                command,
                description: descValue,
            });
        } else {
            const newItem = {...props.checklistItem};
            newItem.title = finalTitle;
            newItem.command = command;
            newItem.description = descValue;
            newItem.task_actions = taskActions;
            props.onUpdateChecklistItem?.(newItem);
        }
    };

    const handleSaveAndAddNew = () => {
        handleSave();
        props.onSaveAndAddNew?.();
    };

    const renderRow = (): null | React.ReactNode => {
        const haveTaskActions = taskActions?.length > 0;
        if (
            !isEditing &&
            !shouldShowCheckedChip(props.checklistItem) &&
            !assigneeID &&
            !hasRoleAssignee &&
            !command &&
            !dueDate &&
            !haveTaskActions
        ) {
            // when not editing, hide row when nothing is set
            return null;
        }
        return (
            <Row>
                {renderCheckedChip()}
                {renderAssignTo()}
                {renderDueDate()}
                {renderCommand()}
                {renderTaskActions()}
            </Row>
        );
    };

    const isAssigneeOnlyLocked = Boolean(
        assigneeOnlyComplete && assigneeID && assigneeID !== currentUserId,
    );

    const checkBoxButton = (
        <CheckBoxButton
            readOnly={props.readOnly}
            disabled={
                isSkipped() ||
                props.playbookRunId === undefined ||
                props.newItem ||
                isAssigneeOnlyLocked
            }
            item={props.checklistItem}
            onChange={(item: ChecklistItemState) => {
                if (
                    betaFeaturesEnabled &&
                    item === ChecklistItemState.Closed &&
                    requirements.length > 0 &&
                    props.playbookRunId
                ) {
                    setFillRequirementsEditMode(false);
                    setShowFillRequirementsModal(true);
                    return Promise.resolve({cancelled: true});
                }
                return props.onChange?.(item);
            }}
            onReadOnlyInteract={props.onReadOnlyInteract}
        />
    );

    const content = (
        <DraggableWrapper
            lang={locale}
            dir={isRtlLocale(locale) ? 'rtl' : 'ltr'}
            ref={props.draggableProvided?.innerRef}
            {...props.draggableProvided?.draggableProps}
        >
            {props.conditionHeader}
            <ItemContainer
                data-testid='checkbox-item-container'
                $editing={isEditing}
                $hoverMenuItemOpen={isHoverMenuItemOpen}
                $disabled={props.readOnly || isSkipped()}
                $hasCondition={props.hasCondition ?? false}
                $isPlaybookEditor={isPlaybookEditor}
                $bulkEditMode={props.bulkEditMode ?? false}
                $isSelected={props.isSelected ?? false}
                onClick={props.bulkEditMode && props.onItemSelect && !isEditing ? (e) => {
                    e.stopPropagation();
                    props.onItemSelect?.();
                } : undefined}
            >
                <CheckboxContainer>
                    {!props.readOnly && !props.dragging &&
                    <ChecklistItemHoverMenu
                        playbookRunId={props.playbookRunId}
                        participantUserIds={props.participantUserIds}
                        teamId={props.teamId}
                        channelId={props.channelId}
                        checklistNum={props.checklistNum}
                        itemNum={props.itemNum}
                        isSkipped={isSkipped()}
                        onEdit={() => setIsEditing(true)}
                        isEditing={isEditing}
                        onChange={props.onChange}
                        description={props.checklistItem.description}
                        showDescription={showDescription}
                        toggleDescription={toggleDescription}
                        assignee_id={assigneeID || ''}
                        assignee_type={assigneeType}
                        assignee_only_complete={assigneeOnlyComplete}
                        onAssigneeChange={onAssigneeChange}
                        onExtraOptionSelected={onExtraOptionSelected}
                        onAssigneeOnlyCompleteChange={canChangeAssignee ? onAssigneeOnlyCompleteChange : undefined}
                        assigneeEditable={canChangeAssignee}
                        assigneeDisabledReason={assigneeDisabledReason}
                        roleOptions={roleOptions}
                        runOwnerId={props.runOwnerId}
                        runCreatorId={props.runCreatorId}
                        due_date={props.checklistItem.due_date}
                        onDueDateChange={onDueDateChange}
                        onDuplicateChecklistItem={props.onDuplicateChecklistItem}
                        onDeleteChecklistItem={props.onDeleteChecklistItem}
                        onItemOpenChange={(isOpen) => {
                            setIsHoverMenuItemOpen(isOpen);
                            onAssigneeMenuOpenChange(isOpen);
                        }}
                        onAddConditional={props.onAddConditional}
                        hasCondition={Boolean(props.checklistItem.condition_id)}
                        onRemoveFromCondition={props.onRemoveFromCondition}
                        onAssignToCondition={props.onAssignToCondition}
                        availableConditions={props.availableConditions}
                        propertyFields={props.propertyFields}
                        isChannelChecklist={props.isChannelChecklist}
                        onAddRequirement={isPlaybookEditor && betaFeaturesEnabled ? () => setShowAddRequirementModal(true) : undefined}
                        hasRequirements={requirements.length > 0}
                        requirementsDisabledReason={
                            isPlaybookEditor && betaFeaturesEnabled && haveAtleastOneEnabledAction(taskActions) && requirements.length === 0 ? formatMessage({defaultMessage: 'Disable the message trigger before adding task requirements.'}) : undefined
                        }
                    />
                    }
                    <DragButton
                        title={formatMessage({defaultMessage: 'Drag me to reorder'})}
                        className={'icon icon-drag-vertical'}
                        {...props.draggableProvided?.dragHandleProps}
                        $isVisible={!props.readOnly && !props.dragDisabled}
                        $isDragging={props.dragging}
                    />
                    {isAssigneeOnlyLocked ? (

                        // Disabled inputs don't fire pointer events; wrap so the reason is still discoverable on hover.
                        <WithTooltip
                            id='assignee-only-complete-checkbox-tooltip'
                            title={formatMessage({defaultMessage: 'Only the assignee can complete the task'})}
                        >
                            <AssigneeOnlyLockedCheckboxWrapper>
                                {checkBoxButton}
                            </AssigneeOnlyLockedCheckboxWrapper>
                        </WithTooltip>
                    ) : checkBoxButton}
                    <ConditionIndicator
                        checklistItem={props.checklistItem}
                        tooltipMessage={getConditionTooltip(props.checklistItem)}
                    />
                    <ChecklistItemTitleWrapper
                        onClick={() => props.collapsibleDescription && props.checklistItem.description !== '' && toggleDescription()}
                    >
                        <ChecklistItemTitle
                            editingItem={isEditing}
                            onEdit={setTitleValue}
                            value={titleValue}
                            skipped={isSkipped()}
                            clickable={props.collapsibleDescription && props.checklistItem.description !== ''}
                            onDeleteEmpty={props.newItem ? props.cancelAddingItem : props.onDeleteChecklistItem}
                            onSaveAndAddNew={props.onSaveAndAddNew ? handleSaveAndAddNew : undefined}
                        />
                    </ChecklistItemTitleWrapper>
                </CheckboxContainer>
                {(descValue || isEditing) &&
                <ChecklistItemDescription
                    editingItem={isEditing}
                    showDescription={showDescription}
                    onEdit={setDescValue}
                    value={descValue}
                    onSave={handleSave}
                    onSaveAndAddNew={props.onSaveAndAddNew ? handleSaveAndAddNew : undefined}
                    title={titleValue}
                />
                }
                {betaFeaturesEnabled && requirements.length > 0 && (
                    <RequirementsAccordion
                        requirements={requirements}
                        editMode={isPlaybookEditor}
                        isTaskComplete={props.checklistItem.state === ChecklistItemState.Closed}
                        readOnly={props.readOnly || isSkipped()}
                        onComplete={!isPlaybookEditor && props.playbookRunId && !isAssigneeOnlyLocked ? () => {
                            setFillRequirementsEditMode(false);
                            setShowFillRequirementsModal(true);
                        } : undefined}
                        onEditValues={!isPlaybookEditor && props.playbookRunId ? () => {
                            setFillRequirementsEditMode(true);
                            setShowFillRequirementsModal(true);
                        } : undefined}
                    />
                )}
                {isEditing && renderAssigneeEditor()}
                {renderRow()}
                {isEditing &&
                <CancelSaveButtons
                    onCancel={() => {
                        setIsEditing(false);
                        setTitleValue(localizeStoredPresetValue(props.checklistItem.title, locale));
                        setDescValue(localizeStoredPresetValue(props.checklistItem.description, locale));
                        discardPendingLock();
                        props.cancelAddingItem?.();
                    }}
                    onSave={handleSave}
                />
                }
            </ItemContainer>
            {showAddRequirementModal && betaFeaturesEnabled && (
                <EditRequirementsModal
                    initialRequirements={requirements}
                    onConfirm={(nextRequirements: TaskRequirement[]) => {
                        const nextItem = {
                            ...props.checklistItem,
                            requirements: nextRequirements,
                        };

                        // Requirements and mark-as-done message triggers are mutually exclusive.
                        if (nextRequirements.length > 0 && haveAtleastOneEnabledAction(taskActions)) {
                            nextItem.task_actions = [];
                            setTaskActions([]);
                        }
                        props.onUpdateChecklistItem?.(nextItem);
                        setShowAddRequirementModal(false);
                    }}
                    onCancel={() => setShowAddRequirementModal(false)}
                />
            )}
            {showFillRequirementsModal && betaFeaturesEnabled && (
                <FillRequirementsModal
                    taskTitle={props.checklistItem.title}
                    requirements={requirements}
                    editMode={fillRequirementsEditMode}
                    isTaskComplete={props.checklistItem.state === ChecklistItemState.Closed}
                    onSave={async (values: Record<string, string>) => {
                        const currentState = (props.checklistItem.state || ChecklistItemState.Open) as ChecklistItemState;
                        const response = await props.onChange?.(currentState, values);
                        if (response?.error) {
                            toaster.add({
                                content: formatMessage({defaultMessage: 'Failed to save requirements.'}),
                                toastStyle: ToastStyle.Failure,
                            });
                            throw response.error;
                        }
                        setShowFillRequirementsModal(false);
                        setFillRequirementsEditMode(false);
                    }}
                    onSaveAndComplete={async (values: Record<string, string>) => {
                        const response = await props.onChange?.(ChecklistItemState.Closed, values);
                        if (response?.error) {
                            toaster.add({
                                content: formatMessage({defaultMessage: 'Failed to save requirements.'}),
                                toastStyle: ToastStyle.Failure,
                            });
                            throw response.error;
                        }
                        setShowFillRequirementsModal(false);
                        setFillRequirementsEditMode(false);
                    }}
                    onCancel={() => {
                        setShowFillRequirementsModal(false);
                        setFillRequirementsEditMode(false);
                    }}
                />
            )}
        </DraggableWrapper>
    );

    if (props.dragging) {
        return <FloatingPortal>{content}</FloatingPortal>;
    }

    return content;
};

