import React from 'react';
import styled from 'styled-components';
import {useIntl} from 'react-intl';
import {WithTooltip} from '@workspace/shared/components/tooltip';

import {getCurrentChannel} from 'mattermost-redux/selectors/entities/channels';
import {GlobalState} from '@mattermost/types/store';

import {useAppSelector} from 'src/hooks/redux';

import {useRunFollowers, useRunMetadata} from 'src/hooks';
import LeftChevron from 'src/components/assets/icons/left_chevron';
import FollowButton from 'src/components/backstage/follow_button';
import ExternalLink from 'src/components/assets/icons/external_link';
import {pluginUrl} from 'src/browser_routing';

import {
    RHSTitleButton,
    RHSTitleContainer,
    RHSTitleLink,
    RHSTitleStyledButtonIcon,
} from './rhs_title_common';

interface Props {
    onBackClick: () => void;
    runID: string;
    runName: string;
    isPlaybookRun: boolean;
}

const getCurrentChannelName = (state: GlobalState) => getCurrentChannel(state)?.display_name;

const RHSRunDetailsTitle = (props: Props) => {
    const {formatMessage} = useIntl();

    const [metadata] = useRunMetadata(props.runID);
    const followState = useRunFollowers(metadata?.followers || []);
    const currentChannelName = useAppSelector(getCurrentChannelName);

    return (
        <RHSTitleContainer>
            <WithTooltip
                id='back-to-checklists'
                title={formatMessage({defaultMessage: 'Back to checklists'})}
            >
                <RHSTitleButton
                    onClick={props.onBackClick}
                    data-testid='back-button'
                >
                    <LeftChevron/>
                </RHSTitleButton>
            </WithTooltip>

            <WithTooltip
                id='view-run-details'
                title={formatMessage({defaultMessage: 'Go to overview'})}
            >
                <RHSTitleLink
                    data-testid='rhs-title'
                    role={'button'}
                    to={pluginUrl(`/runs/${props.runID}?from=channel_rhs_title`)}
                >
                    {formatMessage({defaultMessage: 'Checklist'})}
                    <RHSTitleStyledButtonIcon>
                        <ExternalLink/>
                    </RHSTitleStyledButtonIcon>
                </RHSTitleLink>
            </WithTooltip>
            <VerticalLine/>
            <ChannelNameText>
                {currentChannelName}
            </ChannelNameText>
            {props.isPlaybookRun &&
            <FollowingWrapper>
                <FollowButton
                    runID={props.runID}
                    followState={metadata ? followState : undefined}
                />
            </FollowingWrapper>
            }
        </RHSTitleContainer>
    );
};

const VerticalLine = styled.div`
    height: 24px;
    border-inline-start: 1px solid var(--center-channel-color);
    opacity: 0.16;
    margin: 0 8px;
`;

const ChannelNameText = styled.div`
    overflow: hidden;
    color: rgba(var(--center-channel-color-rgb), 0.56);
    font-family: var(--workspace-font-family, "Thmanyah Sans", sans-serif);
    font-size: 12px;
    font-weight: 400;
    line-height: 20px;
    text-overflow: ellipsis;
`;

const FollowingWrapper = styled.div`
    display: flex;
    flex: 1;
    justify-content: flex-end;
`;

export default RHSRunDetailsTitle;
