import React, {useEffect, useState} from 'react';
import {useIntl} from 'react-intl';
import {Modal} from 'react-bootstrap';
import styled from 'styled-components';
import {getProfilesInChannel, searchProfiles} from 'mattermost-redux/actions/users';
import {UserProfile} from '@mattermost/types/users';
import {LightningBoltOutlineIcon} from '@mattermost/compass-icons/components';
import {OptionTypeBase, StylesConfig} from 'react-select';
import {General} from 'mattermost-redux/constants';

import {useAppDispatch, useAppSelector} from 'src/hooks/redux';

import GenericModal from 'src/components/widgets/generic_modal';
import {PlaybookRun} from 'src/types/playbook_run';
import {useManageRunMembership} from 'src/graphql/hooks';

import CheckboxInput from 'src/components/backstage/runs_list/checkbox_input';

import {isCurrentUserChannelMember} from 'src/selectors';

import ProfileAutocomplete from 'src/components/backstage/profile_autocomplete';

import {useChannel, useIsDMGM} from 'src/hooks';

interface Props {
    playbookRun: PlaybookRun;
    id: string;
    title: React.ReactNode;
    show: boolean;
    hideModal: () => void;
}

const AddParticipantsModal = ({playbookRun, id, title, show, hideModal}: Props) => {
    const {formatMessage} = useIntl();
    const dispatch = useAppDispatch();
    const [profiles, setProfiles] = useState<UserProfile[]>([]);
    const {addToRun} = useManageRunMembership(playbookRun.id);
    const [forceAddToChannel, setForceAddToChannel] = useState(false);
    const [channel, meta] = useChannel(playbookRun.channel_id);
    const isChannelMember = useAppSelector(isCurrentUserChannelMember(playbookRun.channel_id));
    const isPrivateChannelWithAccess = meta.error === null && channel?.type === General.PRIVATE_CHANNEL;

    // Participants are limited to channel members in DM/GM runs.
    const isDMGM = useIsDMGM(playbookRun);
    const [channelMembers, setChannelMembers] = useState<UserProfile[]>([]);

    // For DM/GM channels, fetch channel members once
    useEffect(() => {
        if (isDMGM && playbookRun.channel_id) {
            dispatch(getProfilesInChannel(playbookRun.channel_id, 0, 100) as any)
                .then((result: {data?: UserProfile[]}) => {
                    setChannelMembers(result?.data ?? []);
                })
                .catch(() => setChannelMembers([]));
        }
    }, [isDMGM, playbookRun.channel_id, dispatch]);

    // For DM/GM runs, filter channel members locally (can't add non-members to DM/GM)
    // For team-based runs, filter by team membership via server search
    const searchUsers = (term: string) => {
        if (isDMGM) {
            const lowerTerm = term.toLowerCase();
            const filtered = channelMembers.filter((user) =>
                user.username.toLowerCase().includes(lowerTerm) ||
                (user.first_name && user.first_name.toLowerCase().includes(lowerTerm)) ||
                (user.last_name && user.last_name.toLowerCase().includes(lowerTerm)) ||
                (user.nickname && user.nickname.toLowerCase().includes(lowerTerm))
            );
            return Promise.resolve({data: filtered});
        }

        if (playbookRun.team_id) {
            return dispatch(searchProfiles(term, {team_id: playbookRun.team_id}));
        }
        return dispatch(searchProfiles(term));
    };

    // Return all channel members for DM/GM (used when search term is empty)
    const getChannelMembersProfiles = () => {
        return Promise.resolve({data: channelMembers});
    };

    const header = (
        <Header>
            {title}
        </Header>
    );

    const renderFooter = () => {
        // For DM/GM channels, don't show "add to channel" options since
        // you can't add members to DM/GM channels
        if (isDMGM) {
            return null;
        }
        if (playbookRun.create_channel_member_on_new_participant) {
            return (
                <FooterExtraInfoContainer>
                    <LightningBoltOutlineIcon
                        size={18}
                        color={'rgba(var(--center-channel-color-rgb), 0.56)'}
                    />
                    <FooterText>
                        {formatMessage({defaultMessage: 'Participants will also be added to the channel linked to this run'})}
                    </FooterText>
                </FooterExtraInfoContainer>
            );
        }
        if (isChannelMember || isPrivateChannelWithAccess) {
            return (
                <StyledCheckboxInput
                    testId={'also-add-to-channel'}
                    text={formatMessage({defaultMessage: 'Also add people to the channel linked to this run'})}
                    checked={forceAddToChannel}
                    onChange={(checked) => setForceAddToChannel(checked)}
                />
            );
        }
        return null;
    };

    const onConfirm = () => {
        const ids = profiles.map((e) => e.id);
        addToRun(ids, forceAddToChannel);
        hideModal();
    };

    return (
        <GenericModal
            id={id}
            modalHeaderText={header}
            show={show}
            onHide={hideModal}

            confirmButtonText={formatMessage({defaultMessage: 'Add'})}
            handleConfirm={onConfirm}
            isConfirmDisabled={!profiles || profiles.length === 0}

            onExited={() => {
                setProfiles([]);
                setForceAddToChannel(false);
            }}

            isConfirmDestructive={false}
            autoCloseOnCancelButton={true}
            autoCloseOnConfirmButton={false}
            enforceFocus={true}
            footer={renderFooter()}
            components={{
                Header: ModalHeader,
                FooterContainer: StyledFooterContainer,
            }}
        >
            <ProfileAutocomplete
                searchProfiles={searchUsers}
                getProfiles={isDMGM ? getChannelMembersProfiles : undefined}
                userIds={playbookRun.participant_ids}
                isDisabled={false}
                isMultiMode={true}
                showDefaultOptions={isDMGM}
                customSelectStyles={selectStyles}
                setValues={setProfiles}
                placeholder={isDMGM ?
                    formatMessage({defaultMessage: 'Select channel members'}) :
                    formatMessage({defaultMessage: 'Search for people'})
                }
            />
        </GenericModal>
    );
};

const ModalHeader = styled(Modal.Header)`
    &&&& {
        margin-bottom: 16px;
    }
`;

const Header = styled.div`
    display: flex;
    flex-direction: row;
`;

const StyledFooterContainer = styled.div`
    display: flex;
    width: 100%;
    flex-direction: row-reverse;
    align-items: center;
`;

const FooterExtraInfoContainer = styled.div`
    display: flex;
    flex-direction: row;
    align-items: center;
    margin-inline-end: auto;
    color: rgba(var(--center-channel-color-rgb), 0.56);
    font-size: 14px;
    font-weight: 400;
    line-height: 20px;
    text-align: start;
`;

const FooterText = styled.span`
    margin-inline-start: 10px;
`;

const StyledCheckboxInput = styled(CheckboxInput)`
    padding-block: 10px;
    padding-inline: 0 16px;
    margin-inline-end: auto;
    font-weight: normal;
    white-space: normal;

    &:hover {
        background-color: transparent;
    }
`;

const selectStyles: StylesConfig<OptionTypeBase, boolean> = {
    control: (provided, {isDisabled}) => ({
        ...provided,
        backgroundColor: isDisabled ? 'rgba(var(--center-channel-bg-rgb),0.16)' : 'var(--center-channel-bg)',
        border: '1px solid rgba(var(--center-channel-color-rgb), 0.16)',
        minHeight: '48px',
        fontSize: '16px',
        '&&:before': {content: 'none'},
    }),
    placeholder: (provided) => ({
        ...provided,
        marginInlineStart: '8px',
    }),
    input: (provided) => ({
        ...provided,
        marginInlineStart: '8px',
        color: 'var(--center-channel-color)',
    }),
    multiValue: (provided) => ({
        ...provided,
        backgroundColor: 'rgba(var(--center-channel-color-rgb), 0.08)',
        borderRadius: '16px',
        paddingInlineStart: '8px',
        overflow: 'hidden',
        height: '32px',
        alignItems: 'center',
    }),
    multiValueLabel: (provided) => ({
        ...provided,
        paddingBlock: 0,
        paddingInline: 0,
        paddingInlineStart: 0,
        lineHeight: '18px',
        color: 'var(--center-channel-color)',
    }),
    multiValueRemove: (provided) => ({
        ...provided,
        color: 'rgba(var(--center-channel-bg-rgb), 0.80)',
        backgroundColor: 'rgba(var(--center-channel-color-rgb),0.32)',
        borderRadius: '50%',
        margin: '4px',
        paddingBlock: 0,
        paddingInline: 0,
        cursor: 'pointer',
        width: '16px',
        height: '16px',
        ':hover': {
            backgroundColor: 'rgba(var(--center-channel-color-rgb),0.56)',
        },
        ':active': {
            backgroundColor: 'rgba(var(--center-channel-color-rgb),0.56)',
        },
        '> svg': {
            height: '16px',
            width: '16px',
        },
    }),
};

export default AddParticipantsModal;
