import ArabicPresetTemplates from './template_data_ar';
import {PresetTemplates as EnglishPresetTemplates, PresetTemplate} from './template_data_en';

export type {PresetTemplate} from './template_data_en';

// Arabic is the default content. Stable keys retain existing template URLs.
export const PresetTemplates: PresetTemplate[] = ArabicPresetTemplates.map((preset, index) => ({
    ...preset,
    key: EnglishPresetTemplates[index].title,
}));

export default PresetTemplates;
