const selectGlobalStyles = (classNamePrefix: string) => css`
    .${classNamePrefix}__control.${classNamePrefix}__control {
        border: none;
        border-radius: 4px;
        background-color: rgba(var(--center-channel-color-rgb), 0.04);
        box-shadow: inset 0 0 0 1px rgba(var(--center-channel-color-rgb), 0.16);
        font-size: 14px;
        transition: box-shadow 0.15s ease, border-color 0.15s ease;
        transition-delay: 0s;

        &--is-focused {
            box-shadow: inset 0 0 0 1px var(--button-bg);
        }
    }

    .${classNamePrefix}__control--is-disabled {
        opacity: 0.56;
    }

    .${classNamePrefix}__control,
    .${classNamePrefix}__menu {
        font-family: var(--workspace-font-family, "Thmanyah Sans", sans-serif);
        text-align: start;
        .${classNamePrefix}__menu-list {
            border: none;
            border-radius: var(--radius-s);
            background-color: var(--center-channel-bg);
        }

        .${classNamePrefix}__input {
            background: transparent;
            color: var(--center-channel-color);
        }

        .${classNamePrefix}__placeholder {
            color: rgba(var(--center-channel-color-rgb), 0.64);
        }

        .${classNamePrefix}__option {
            color: var(--center-channel-color);
            overflow-wrap: anywhere;
        }

        .${classNamePrefix}__option--is-selected {
            background-color: rgba(var(--button-bg-rgb), 0.16);
            color: inherit;
        }

        .${classNamePrefix}__option--is-focused {
            background-color: rgba(var(--button-bg-rgb), 0.08);
        }

        .${classNamePrefix}__option {
            &:active {
                background-color: rgba(var(--button-bg-rgb), 0.16);
            }
        }

        .${classNamePrefix}__single-value {
            color: var(--center-channel-color);
        }

        .${classNamePrefix}__multi-value {
            height: 20px;
            padding-inline-start: 8px;
            border-radius: 10px;
            background-color: rgba(var(--center-channel-color-rgb), 0.08);
            line-height: 19px;

            .${classNamePrefix}__multi-value__label {
                padding-block: 0;
                padding-inline: 0;
                color: var(--center-channel-color);
            }

            .${classNamePrefix}__multi-value__remove {
                color: rgba(var(--center-channel-color-rgb), 0.64);

                &:hover {
                    background: rgba(var(--error-text-color-rgb), 0.16);
                    color: var(--error-text);
                }
            }
        }
    }
`;

export const GlobalSelectStyle = createGlobalStyle`
    #app-bar-icon-workspace .app-bar__icon-inner {
        position: relative;

        img {
            opacity: 0;
        }

        &::after {
            position: absolute;
            inset: 0;
            background-color: rgba(var(--sidebar-text-rgb), 0.64);
            content: '';
            mask: url(${appBarIcon}) center / contain no-repeat;
            pointer-events: none;
        }
    }

    #app-bar-icon-workspace:hover .app-bar__icon-inner::after,
    #app-bar-icon-workspace.app-bar__icon--active .app-bar__icon-inner::after {
        background-color: rgba(var(--sidebar-text-rgb), 0.8);
    }

    @font-face {
        font-family: "Thmanyah Sans";
        font-style: normal;
        font-weight: 400;
        font-display: swap;
        src: url(${regularFont}) format('opentype');
    }

    @font-face {
        font-family: "Thmanyah Sans";
        font-style: normal;
        font-weight: 500;
        font-display: swap;
        src: url(${mediumFont}) format('opentype');
    }

    @font-face {
        font-family: "Thmanyah Sans";
        font-style: normal;
        font-weight: 700;
        font-display: swap;
        src: url(${boldFont}) format('opentype');
    }

    ${selectGlobalStyles('playbooks-rselect')}
    ${selectGlobalStyles('property-select')}
    ${selectGlobalStyles('channel-selector')}
    ${selectGlobalStyles('playbook-react-select')}
    ${selectGlobalStyles('profile-autocomplete')}
    ${selectGlobalStyles('assign-owner-selector')}
    ${selectGlobalStyles('invite-users-selector')}
`;

const commonSelectStyle = css`
    flex-grow: 1;
    background-color: var(--center-channel-bg);
`;

// React Select's generated styles also need the host palette, including portalled menus.
const selectTheme = (theme: Theme): Theme => ({
    ...theme,
    colors: {
        ...theme.colors,
        primary: 'var(--button-bg)',
        primary25: 'rgba(var(--button-bg-rgb), 0.08)',
        primary50: 'rgba(var(--button-bg-rgb), 0.16)',
        primary75: 'rgba(var(--button-bg-rgb), 0.24)',
    },
});

export const StyledSelect = styled(Select).attrs((props) => {
    return {
        classNamePrefix: 'playbooks-rselect',
        ...props,
        theme: selectTheme,
    };
})`
    ${commonSelectStyle}

    ${({classNamePrefix}) => css`
        .${classNamePrefix}__multi-value {
            padding-inline-start: 6px;
        }
    `}

`;

