import React from 'react';
import styled from 'styled-components';

import {IconListNumbers} from '@tabler/icons-react';

interface Props {
    id?: string;
    className?: string;
    color?: string;
    size?: number | string;
}

const Icon = styled(IconListNumbers)`
    width: 20px;
    height: 20px;
`;

const PlaybooksProductIcon = (props: Props) => (
    <Icon
        id={props.id}
        className={[props.className, 'TablerIcon LogoIcon'].filter(Boolean).join(' ')}
        color={props.color ?? 'currentColor'}
        size={props.size ?? 22}
    />
);

export default PlaybooksProductIcon;
