import React, {ReactNode} from 'react';
import styled from 'styled-components';
import {getTeam} from 'mattermost-redux/selectors/entities/teams';
import {GlobalState} from '@mattermost/types/store';

import {Team} from '@mattermost/types/teams';
import Scrollbars from 'react-custom-scrollbars';

import {WithTooltip} from '@workspace/shared/components/tooltip';

import {useAppSelector} from 'src/hooks/redux';

import {renderThumbVertical, renderTrackHorizontal, renderView} from 'src/components/rhs/rhs_shared';

import Group from './group';

export interface GroupItem {
    id?: string;
    icon: string;
    itemMenu?: React.ReactNode;
    display_name: string;
    className: string;
    areaLabel: string;
    link: string;
    isCollapsed: boolean;
}

export interface SidebarGroup {
    id: string;
    display_name: string;
    collapsed: boolean;
    items: Array<GroupItem>;
    afterGroup?: ReactNode;
}

interface SidebarProps {
    team_id: string;
    groups: Array<SidebarGroup>;
    headerDropdown: React.ReactNode;
}

const selectTeam = (teamId: string) => (state: GlobalState): Team | undefined => getTeam(state, teamId);

const Sidebar = (props: SidebarProps) => {
    const team = useAppSelector(selectTeam(props.team_id));

    const teamName = (
        <TeamName>
            {team?.display_name}
        </TeamName>
    );

    return (
        <SidebarComponent>
            <Header>
                {team?.description ? (
                    <WithTooltip
                        id='team-name__tooltip'
                        title={team?.description}
                    >
                        {teamName}
                    </WithTooltip>
                ) : (
                    teamName
                )}
                {props.headerDropdown}
            </Header>
            <Scrollbars
                autoHide={true}
                autoHideTimeout={500}
                autoHideDuration={500}
                renderThumbVertical={renderThumbVertical}
                renderView={renderView}
                renderTrackHorizontal={renderTrackHorizontal}
                style={{
                    position: 'relative',
                    marginBottom: '40px',
                }}
            >
                {props.groups.map((group) => {
                    return (
                        <Group
                            key={group.id}
                            group={group}
                        />
                    );
                })}
            </Scrollbars>
        </SidebarComponent>
    );
};

const SidebarComponent = styled.div`
    position: fixed;
    z-index: 16;
    display: flex;
    width: 241px;
    height: 100%;
    flex-direction: column;
    border-inline-end: 1px solid rgba(var(--center-channel-color-rgb), 0.12);

    @media (width <= 767px) {
        position: relative;
        width: 100%;
        min-height: 0;
        border-inline-end: none;
    }

    background-color: var(--center-channel-bg);
`;

const Header = styled.div`
    display: flex;
    height: 52px;
    flex: initial;
    flex-flow: row nowrap;
    align-items: center;
    justify-content: space-between;
    padding-block: 0;
    padding-inline: 16px;
    margin: 0;
    gap: 8px;
`;

const TeamName = styled.h1`
    display: inline-block;
    overflow: hidden;
    margin: 0;
    color: var(--center-channel-color);
    cursor: pointer;
    font-family: var(--workspace-font-family, "Thmanyah Sans", sans-serif);
    font-size: 17px;
    font-weight: 700;
    line-height: 24px;
    text-overflow: ellipsis;
    white-space: nowrap;
`;

export default Sidebar;
