import React, {useEffect} from 'react';

import {getUser} from 'mattermost-redux/selectors/entities/users';
import {getUser as fetchUser} from 'mattermost-redux/actions/users';

import {useAppDispatch, useAppSelector} from 'src/hooks/redux';

import {ButtonIcon} from 'src/components/assets/buttons';
import {navigateToUrl} from 'src/browser_routing';

interface Props {
    userId: string;
    teamName: string | null;
}

export const SendMessageButton = React.forwardRef<HTMLButtonElement, Props>((props, ref) => {
    const dispatch = useAppDispatch();
    const user = useAppSelector((state) => getUser(state, props.userId));

    useEffect(() => {
        if (!user) {
            dispatch(fetchUser(props.userId));
        }
    }, [props.userId]);

    const onClick = () => {
        if (!props.teamName || !user) {
            return;
        }
        navigateToUrl(`/${props.teamName}/messages/@${user.username}`);
    };

    return (
        <ButtonIcon
            ref={ref}
            style={{margin: 'auto 0'}}
            className={'icon-send'}
            onClick={onClick}
        />
    );
});
SendMessageButton.displayName = 'SendMessageButton';
