import React from 'react';

import styled from 'styled-components';
import {useIntl} from 'react-intl';

import {getCurrentUser} from 'mattermost-redux/selectors/entities/common';
import {getCurrentTeamId} from 'mattermost-redux/selectors/entities/teams';

import {isRtlLocale} from 'src/utils';

import {useAppSelector} from 'src/hooks/redux';

import {savePlaybook} from 'src/client';
import {StyledSelect} from 'src/components/backstage/styles';
import {setPlaybookDefaults} from 'src/types/playbook';
import {usePlaybooksRouting} from 'src/hooks';

import {useLHSRefresh} from 'src/components/backstage/lhs_navigation';

import TemplateItem from './template_item';
import PresetTemplates, {PresetTemplate} from './template_data';
import {localizePresetTemplate} from './template_localization';

interface Props {
    templates?: PresetTemplate[];
}

interface TemplateDropdownProps {
    template?: string
    onTemplateSet: (template?: string) => void
}

export const TemplateDropdown = (props: TemplateDropdownProps) => {
    const intl = useIntl();
    const {formatMessage, locale} = intl;
    const presetTemplateOptions = PresetTemplates.map((template: PresetTemplate) => ({
        label: localizePresetTemplate(template, intl).title,
        value: template.key ?? template.title,
    }));

    const handleTemplateSet = (option: {value: string}) => {
        props.onTemplateSet(option.value);
    };

    return (
        <StyledSelect
            isRtl={isRtlLocale(locale)}
            filterOption={null}
            isMulti={false}
            placeholder={formatMessage({defaultMessage: 'Select an example'})}
            onChange={handleTemplateSet}
            options={presetTemplateOptions}
            value={presetTemplateOptions.find((val) => val.value === props?.template)}
            isClearable={false}
            maxMenuHeight={380}
        />
    );
};

const SelectorGrid = styled.div`
	display: grid;
    padding-block: 0 100px;
    padding-inline: 0;
    gap: 2.5rem;
	grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
    place-items: flex-start center;
`;

const instantCreatePlaybook = async (template: PresetTemplate, teamID: string, title: string): Promise<string> => {
    const pb = setPlaybookDefaults(template.template);
    pb.public = true;
    pb.team_id = teamID;
    if (title !== '') {
        pb.title = title;
    }
    const data = await savePlaybook(pb);

    return data?.id;
};

const TemplateSelector = ({templates = PresetTemplates}: Props) => {
    const intl = useIntl();
    const teamId = useAppSelector(getCurrentTeamId);
    const currentUser = useAppSelector(getCurrentUser);
    const {edit} = usePlaybooksRouting();
    const refreshLHS = useLHSRefresh();

    return (
        <SelectorGrid>
            {templates.map((template: PresetTemplate) => {
                const localizedTemplate = localizePresetTemplate(template, intl);
                return (
                    <TemplateItem
                        key={template.title}
                        label={localizedTemplate.label}
                        title={localizedTemplate.title}
                        description={localizedTemplate.description ?? ''}
                        color={template.color}
                        icon={template.icon}
                        author={template.author}
                        labelColor={template.labelColor}
                        onSelect={async () => {
                            const isTutorial = template.title === 'Learn how to use playbooks';
                            const title = isTutorial ? '' : intl.formatMessage(
                                {id: 'playbooks.templates.personalized_title', defaultMessage: "{name}'s {template}"},
                                {name: '@' + currentUser.username, template: localizedTemplate.title},
                            );
                            const playbookID = await instantCreatePlaybook(localizedTemplate, teamId, title);
                            refreshLHS();
                            edit(playbookID);
                        }}
                    />
                );
            })}

        </SelectorGrid>
    );
};

export default TemplateSelector;
