const ID = 'playbooks_run_playbook_dialog';

export const makeModalDefinition = (
    playbookId: string | undefined,
    triggerChannelId: string | undefined,
    teamId: string,
    onRunCreated: (runId: string, channelId: string, statsData: object) => void,
) => ({
    modalId: ID,
    dialogType: ApolloWrappedModal,
    dialogProps: {playbookId, triggerChannelId, teamId, onRunCreated},
});

type Props = {
    playbookId?: string,
    triggerChannelId?: string,
    teamId: string,
    onRunCreated: (runId: string, channelId: string, statsData: object) => void,
} & Partial<ComponentProps<typeof GenericModal>>;

export const RunPlaybookModal = ({
    playbookId,
    triggerChannelId,
    teamId,
    onRunCreated,
    ...modalProps
}: Props) => {
    const {formatMessage} = useIntl();
    const dispatch = useAppDispatch();
    const {onHide, ...restModalProps} = modalProps;

    const [step, setStep] = useState(playbookId === undefined ? 'select-playbook' : 'run-details');
    const [selectedPlaybookId, setSelectedPlaybookId] = useState(playbookId);
    const [playbook, {isFetching: playbookLoading, error: playbookError}] = usePlaybook(selectedPlaybookId || '');
    const playbookAttributes = usePlaybookAttributes(selectedPlaybookId || '');

    // useRestPlaybook's isFetching flips to false as soon as the fetch is fired, not once it
    // resolves (see useThing), so it can't signal "still loading" here — restPlaybook itself
    // stays undefined until the fetch (or a cache hit) actually settles, so that's the check to use.
    //
    // useThing also never resets its cached value back to undefined when selectedPlaybookId
    // changes, and has no fetch cancellation — so a slow fetch for a previously-selected
    // playbook can resolve after a newer one is already selected and clobber restPlaybook with
    // the wrong playbook's data. Guard against that the same way `playbook` (the GraphQL side)
    // is already guarded at the effect below (`playbook.id !== selectedPlaybookId`): only trust
    // restPlaybook once its id actually matches the currently selected playbook, otherwise treat
    // it the same as still loading.
    const [restPlaybookRaw] = useRestPlaybook(selectedPlaybookId || '');
    const restPlaybook = restPlaybookRaw?.id === selectedPlaybookId ? restPlaybookRaw : undefined;
    const restPlaybookLoading = Boolean(selectedPlaybookId) && restPlaybook === undefined;
    const [runName, setRunName] = useState('');
    const [runSummary, setRunSummary] = useState('');
    const [channelMode, setChannelMode] = useState('');
    const [channelId, setChannelId] = useState('');
    const [createPublicRun, setCreatePublicRun] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const isSubmittingRef = useRef(false);
    const isMountedRef = useRef(true);
    const initializedPlaybookIdRef = useRef<string | undefined>(undefined);
    useEffect(() => {
        return () => {
            isMountedRef.current = false;
        };
    }, []);
    const [submitError, setSubmitError] = useState('');
    const [propertyValues, setPropertyValues] = useState<Record<string, string | number | boolean | null | string[]>>({});
    const canCreatePlaybooks = useCanCreatePlaybooksInTeam(teamId || '');

    const currentChannelId = useAppSelector(getCurrentChannelId);
    const currentChannel = useAppSelector(getCurrentChannel);
    const currentChannelIsDMOrGM = currentChannel?.type === General.DM_CHANNEL || currentChannel?.type === General.GM_CHANNEL;
    const currentUserId = useAppSelector(getCurrentUserId);
    const userId = (playbook?.default_owner_enabled && playbook.default_owner_id) ? playbook.default_owner_id : currentUserId;

    const teammateNameDisplaySetting = useAppSelector(getTeammateNameDisplaySetting) || '';
    const userMap = useUserDisplayNameMap();

    // pickerUserNames captures display names for users selected via the picker
    // that may not be in the Redux team-profiles slice (found via search API).
    const [pickerUserNames, setPickerUserNames] = useState<Record<string, string>>({});
    const handleUserKnown = useCallback((user: {id: string} & Record<string, unknown>) => {
        const name = displayUsername(user as Parameters<typeof displayUsername>[0], teammateNameDisplaySetting);
        setPickerUserNames((prev) => ({...prev, [user.id]: name}));
    }, [teammateNameDisplaySetting]);
    const effectiveUserMap = useMemo(() => ({...userMap, ...pickerUserNames}), [userMap, pickerUserNames]);

    // Ensure user profiles for user-type property values are loaded so the preview
    // resolves IDs to display names even for users outside the first team-profiles page.
    const userIdsInPropertyValues = useMemo(() => {
        if (!playbookAttributes) {
            return [];
        }
        const ids: string[] = [];
        for (const field of playbookAttributes) {
            const val = propertyValues[field.id];
            if (field.type === PropertyFieldType.User && typeof val === 'string' && val) {
                ids.push(val);
            } else if (field.type === PropertyFieldType.Multiuser && Array.isArray(val)) {
                ids.push(...val.filter((v): v is string => typeof v === 'string' && v !== ''));
            }
        }
        return ids;
    }, [playbookAttributes, propertyValues]);

    // Inline: load missing user profiles for user-type property values.
    // Avoids src/hooks/general.ts useEnsureProfiles whose inline useSelector closure
    // breaks useSyncExternalStoreWithSelector memoization and triggers re-render loops.
    const ensureProfilesStore = useStore<GlobalState>();
    useEffect(() => {
        if (userIdsInPropertyValues.length === 0) {
            return;
        }
        const state = ensureProfilesStore.getState();
        const unknownIds = userIdsInPropertyValues.filter((id) => !getUser(state, id));
        if (unknownIds.length > 0) {
            dispatch(getProfilesByIds(unknownIds));
        }
    }, [userIdsInPropertyValues, ensureProfilesStore, dispatch]);

    const isNewChannelOnly = Boolean(restPlaybook?.new_channel_only);

    const hasTemplate = Boolean(playbook?.channel_name_template);

    const playbookInitializationKey = playbook ? JSON.stringify({
        id: playbook.id,
        channelNameTemplate: playbook.channel_name_template ?? '',
        runSummaryTemplateEnabled: playbook.run_summary_template_enabled,
        runSummaryTemplate: playbook.run_summary_template ?? '',
        channelMode: playbook.channel_mode,
        channelId: playbook.channel_id,
        createPublicPlaybookRun: playbook.create_public_playbook_run,
        isNewChannelOnly,
    }) : undefined;

    // Single effect for atomic init: prevents race conditions from independent effects exposing stale state.
    useEffect(() => {
        // Reset form state first; skip isSubmitting if a submission is already in flight
        // to avoid a split-brain where the button looks clickable but isSubmittingRef blocks clicks.
        setPropertyValues({});
        setSubmitError('');
        if (!isSubmittingRef.current) {
            setIsSubmitting(false);
        }

        if (!playbook || playbook.id !== selectedPlaybookId) {
            initializedPlaybookIdRef.current = undefined;
            setRunName('');
            setRunSummary('');
            return;
        }

        if (playbookInitializationKey === initializedPlaybookIdRef.current) {
            return;
        }
        initializedPlaybookIdRef.current = playbookInitializationKey;

        // Pre-fill with the raw channel_name_template so the user can see it (or, when not
        // locked, edit it). Submitting it unedited still resolves correctly — the backend
        // resolves tokens in a user-supplied name the same way it resolves the template itself.
        setRunName(playbook.channel_name_template ?? '');

        setRunSummary(playbook.run_summary_template_enabled ? playbook.run_summary_template : '');
        setChannelMode(isNewChannelOnly ? 'create_new_channel' : playbook.channel_mode);
        setChannelId(playbook.channel_id);
        setCreatePublicRun(playbook.create_public_playbook_run);
    }, [playbook?.id, selectedPlaybookId, playbookInitializationKey]);

    const templateFieldNames = useMemo(() => {
        const names = new Set<string>();
        if (playbook?.channel_name_template) {
            extractTemplateFieldNames(playbook.channel_name_template).forEach((n) => names.add(n.toLowerCase()));
        }
        return names;
    }, [playbook?.channel_name_template]);

    const templateFields = useMemo(() => {
        if (!playbookAttributes || playbookAttributes.length === 0 || templateFieldNames.size === 0) {
            return [];
        }
        const seen = new Set<string>();
        return playbookAttributes.filter((f) => {
            const lower = f.name.toLowerCase();
            if (templateFieldNames.has(lower) && !seen.has(lower)) {
                seen.add(lower);
                return true;
            }
            return false;
        }) as unknown as PropertyField[];
    }, [playbookAttributes, templateFieldNames]);

    // Block submission while attributes are loading for a template that references fields:
    // we cannot validate required-field coverage until the attribute list arrives.
    const attributesLoading = playbookAttributes === undefined && templateFieldNames.size > 0;

    const locked = hasTemplate && (restPlaybook?.channel_name_template_locked ?? false);

    const unmatchedTemplateNames = useMemo(() => {
        if (!playbook?.channel_name_template || templateFieldNames.size === 0) {
            return [];
        }
        if (!playbookAttributes) {
            return [];
        }
        const loadedNames = new Set((playbookAttributes).map((f) => f.name.toLowerCase()));
        return [...templateFieldNames].filter((n) => !loadedNames.has(n));
    }, [templateFieldNames, playbookAttributes, playbook?.channel_name_template]);

    // Preview the resolved name (client-side approximation). Always sourced from the current
    // run-name field content — not just the playbook's own template — so typing a recognized
    // token (e.g. "Release {Version}") previews correctly whether that text came from the
    // template or was typed freehand; the backend resolves tokens in a user-supplied name the
    // same way.
    const runNameHasToken = (/\{[^}]+\}/).test(runName);
    const namePreview = useMemo(() => {
        if (!runNameHasToken) {
            return '';
        }
        return buildTemplatePreview(
            runName,
            (playbookAttributes ?? []) as unknown as PropertyField[],
            propertyValues,
            {
                prefix: playbook?.run_number_prefix,
                userMap: effectiveUserMap,
                ownerUserId: userId,
                creatorUserId: currentUserId,
                nextRunNumber: playbook?.next_run_number,
                ownerFallback: formatMessage({defaultMessage: "Owner's name"}),
                creatorFallback: formatMessage({defaultMessage: "Creator's name"}),
            },
        );
    }, [runName, runNameHasToken, playbook?.run_number_prefix, playbookAttributes, playbook?.next_run_number, propertyValues, effectiveUserMap, userId, currentUserId, formatMessage]);

    const createNewChannel = channelMode === 'create_new_channel' || isNewChannelOnly;

    // The value that will actually be used as the run/channel name: the live preview when the
    // name contains a token (resolved, whether locked or not), otherwise the raw name itself
    // when locked (a locked literal template's raw text IS the final value — nothing to
    // substitute, so there's no separate preview to check against).
    let effectiveResolvedName = '';
    if (runNameHasToken) {
        effectiveResolvedName = namePreview;
    } else if (locked) {
        effectiveResolvedName = runName;
    }

    // Name is required unless the template is locked (authoritative and will be used as-is).
    // When locked, the resolved value must fit within the limit so the backend accepts it;
    // the raw template string itself is not validated against the limit.
    const templateNameValid = effectiveResolvedName === '' || [...effectiveResolvedName].length <= RUN_NAME_MAX_LENGTH;
    const freeNameValid = runName !== '' && [...runName].length <= RUN_NAME_MAX_LENGTH;
    const nameValid = locked ? templateNameValid : freeNameValid;

    const namePreviewTooLong = effectiveResolvedName !== '' && [...effectiveResolvedName].length > RUN_NAME_MAX_LENGTH;

    const requiredFieldsFilled = useMemo(() => templateFields.every((field) => {
        const val = propertyValues[field.id];
        if (val === undefined || val === null || val === '') {
            return false;
        }
        if (Array.isArray(val) && val.length === 0) {
            return false;
        }
        return true;
    }), [templateFields, propertyValues]);

    const isFormValid = !attributesLoading && nameValid && !namePreviewTooLong && requiredFieldsFilled && unmatchedTemplateNames.length === 0 && (createNewChannel || channelId !== '');

    const handleSetChannelMode = useCallback((mode: 'link_existing_channel' | 'create_new_channel') => {
        if (isNewChannelOnly && mode === 'link_existing_channel') {
            return;
        }

        setChannelMode(mode);

        // Default to the current channel when choosing link to the existing channel, we are in a channel context and the playbook does not have a linked channel.
        // Skip the fallback when we're sitting in a DM/GM — the selector
        // excludes DMs/GMs as link targets, so pre-selecting one would be
        // invalid and renders as "Unknown Channel".
        if (mode === 'link_existing_channel' && playbook?.channel_mode === 'create_new_channel' && channelId === '' && currentChannelId && !currentChannelIsDMOrGM) {
            setChannelId(currentChannelId);
        }
    }, [isNewChannelOnly, playbook?.channel_mode, channelId, currentChannelId, currentChannelIsDMOrGM]);

    const onCreatePlaybook = () => {
        dispatch(displayPlaybookCreateModal({}));
        onHide?.();
    };

    const handleSelectPlaybook = useCallback((id: string) => {
        setSelectedPlaybookId(id);
        setStep('run-details');
    }, []);
    const buildStatsData = useCallback((isNewChannel: boolean, isLinkedChannel: boolean): Parameters<typeof onRunCreated>[2] => ({
        playbookId: selectedPlaybookId,
        channelMode,
        public: isNewChannel ? createPublicRun : undefined,
        hasPlaybookChanged: playbookId !== selectedPlaybookId,
        hasNameChanged: runName !== (playbook!.channel_name_template ?? ''),
        hasSummaryChanged: runSummary !== (playbook!.run_summary_template_enabled ? playbook!.run_summary_template : ''),
        hasChannelModeChanged: channelMode !== playbook!.channel_mode,
        hasChannelIdChanged: channelId !== playbook!.channel_id,
        hasPublicChanged: !isLinkedChannel && createPublicRun !== playbook!.create_public_playbook_run,
    }), [selectedPlaybookId, channelMode, createPublicRun, playbookId, runName, runSummary, channelId, playbook]);

    const resetSubmitting = useCallback(() => {
        isSubmittingRef.current = false;
        if (isMountedRef.current) {
            setIsSubmitting(false);
        }
    }, []);

    const onSubmit = useCallback(() => {
        if (!playbook || !selectedPlaybookId || playbook.id !== selectedPlaybookId || isSubmittingRef.current) {
            return;
        }

        // Re-validate at submission time to guard against stale closures where isFormValid
        // may have been computed during a previous render cycle.
        if (!isFormValid) {
            return;
        }

        const isNewChannel = channelMode === 'create_new_channel';
        const isLinkedChannel = channelMode === 'link_existing_channel';

        // isSubmittingRef (ref) and isSubmitting (state) serve different purposes:
        // - isSubmittingRef provides a synchronous guard to prevent double-submission
        //   (checked before the async call, before any React batching).
        // - isSubmitting drives the UI disabled state; it is set via setState so its
        //   update is batched and applied on the next render paint.
        // Both must be set here so the ref guard fires immediately and the button
        // becomes visually disabled on the next frame.
        isSubmittingRef.current = true;
        setSubmitError('');
        setIsSubmitting(true);
        const pvToSend = Object.keys(propertyValues).length > 0 ? propertyValues : undefined;
        let runPromise: ReturnType<typeof createPlaybookRun>;
        try {
            runPromise = createPlaybookRun(
                selectedPlaybookId,
                userId,
                playbook.team_id,
                runName,
                runSummary,
                isLinkedChannel ? channelId : undefined,
                isNewChannel ? createPublicRun : undefined,
                pvToSend,
            );
        } catch {
            resetSubmitting();
            setSubmitError(formatMessage({defaultMessage: 'An error occurred while creating the run.'}));
            return;
        }
        runPromise
            .then((newPlaybookRun) => {
                if (!isMountedRef.current) {
                    resetSubmitting();
                    return;
                }
                resetSubmitting();
                const statsData = buildStatsData(isNewChannel, isLinkedChannel);
                onRunCreated(newPlaybookRun.id, newPlaybookRun.channel_id, statsData);
                onHide?.();
            }).catch(() => {
                if (!isMountedRef.current) {
                    resetSubmitting();
                    return;
                }
                resetSubmitting();
                setSubmitError(formatMessage({defaultMessage: 'An error occurred while creating the run.'}));
            });
    }, [playbook, selectedPlaybookId, isFormValid, propertyValues, userId, runName, runSummary, channelId, createPublicRun, channelMode, playbookId, onHide, onRunCreated, formatMessage, resetSubmitting, buildStatsData]);

    // Start a run tab
    if (step === 'run-details') {
        // Also wait on restPlaybookLoading: the run-name field's readOnly/required behavior
        // depends on restPlaybook.channel_name_template_locked, which fails open (unlocked) while
        // still loading — rendering the interactive form before it resolves would let a locked
        // template briefly show as editable.
        if (selectedPlaybookId && (playbookLoading || restPlaybookLoading) && !submitError) {
            return (
                <StyledGenericModal
                    id={ID}
                    showCancel={false}
                    onHide={onHide}
                    {...restModalProps}
                >
                    <LoadingContainer
                        role='status'
                        aria-label={formatMessage({defaultMessage: 'Loading playbook details…'})}
                    >
                        <LoadingSpinner/>
                    </LoadingContainer>
                </StyledGenericModal>
            );
        }
        if (selectedPlaybookId && playbookError && !playbook) {
            return (
                <StyledGenericModal
                    id={ID}
                    showCancel={false}
                    onHide={onHide}
                    {...restModalProps}
                >
                    <ErrorMessage role='alert'>
                        {formatMessage({defaultMessage: 'Failed to load playbook details. Please close and try again.'})}
                    </ErrorMessage>
                </StyledGenericModal>
            );
        }
        return (
            <StyledGenericModal
                cancelButtonText={formatMessage({defaultMessage: 'Cancel'})}
                confirmButtonText={formatMessage({defaultMessage: 'Start run'})}
                showCancel={true}
                isConfirmDisabled={isSubmitting || !isFormValid}
                handleConfirm={onSubmit}
                autoCloseOnConfirmButton={false}
                enforceFocus={false}
                id={ID}
                modalHeaderText={(
                    <ColContainer>
                        <IconWrapper
                            type='button'
                            aria-label={formatMessage({defaultMessage: 'Back'})}
                            onClick={() => {
                                setSearchTerm('');
                                setStep('select-playbook');
                            }}
                        >
                            <ArrowLeftIcon
                                size={24}
                                color={'rgba(var(--center-channel-color-rgb), 0.56)'}
                            />
                        </IconWrapper>
                        <HeaderTitle>
                            <FormattedMessage defaultMessage='Run playbook'/>
                            <ModalSideheading>{playbook?.title}</ModalSideheading>
                        </HeaderTitle>
                    </ColContainer>
                )}
                onHide={onHide}
                {...restModalProps}
            >
                <Body>
                    <RunNameSection
                        runName={runName}
                        onSetRunName={setRunName}
                        readOnly={locked}
                    />
                    {runNameHasToken && namePreview && (
                        <NamePreview data-testid='run-name-preview'>
                            {formatMessage({defaultMessage: 'Preview: {preview}'}, {preview: namePreview})}
                        </NamePreview>
                    )}
                    {namePreviewTooLong && (
                        <ErrorMessage data-testid='run-name-preview-error'>
                            {locked ?
                                formatMessage({defaultMessage: 'The resolved run name exceeds the {maxLength}-character limit. Shorten the field values used in the template.'}, {maxLength: RUN_NAME_MAX_LENGTH}) :
                                formatMessage({defaultMessage: 'The resolved run name exceeds the {maxLength}-character limit. Shorten the name or use fewer fields.'}, {maxLength: RUN_NAME_MAX_LENGTH})}
                        </ErrorMessage>
                    )}
                    {templateFields.length > 0 && (
                        <PropertyFieldsSection
                            fields={templateFields}
                            values={propertyValues}
                            onSetValues={setPropertyValues}
                            onUserKnown={handleUserKnown}
                        />
                    )}

                    <InlineLabel>{formatMessage({defaultMessage: 'Summary'})}</InlineLabel>
                    <BaseTextArea
                        data-testid={'run-summary-input'}
                        rows={5}
                        value={runSummary}
                        onChange={(e) => setRunSummary(e.target.value)}
                    />
                    <ConfigChannelSection
                        teamId={teamId}
                        channelId={channelId}
                        channelMode={channelMode}
                        createPublicRun={createPublicRun}
                        newChannelOnly={isNewChannelOnly}
                        onSetCreatePublicRun={setCreatePublicRun}
                        onSetChannelMode={handleSetChannelMode}
                        onSetChannelId={setChannelId}
                    />
                    {submitError && <ErrorMessage>{submitError}</ErrorMessage>}
                </Body>
            </StyledGenericModal>
        );
    }

    // Select a playbook tab
    return (
        <StyledGenericModal
            showCancel={false}
            isConfirmDisabled={false}
            id={ID}
            modalHeaderText={(
                <RowContainer>
                    <ColContainer>
                        <HeaderTitle>
                            <FormattedMessage defaultMessage='Run playbook'/>
                        </HeaderTitle>
                        <HeaderButtonWrapper>
                            {canCreatePlaybooks &&
                                <Button
                                    onClick={onCreatePlaybook}
                                    emphasis='tertiary'
                                    size='sm'
                                >
                                    <FormattedMessage defaultMessage='Create new playbook'/>
                                </Button>
                            }
                        </HeaderButtonWrapper>
                    </ColContainer>
                </RowContainer>
            )}
            onHide={onHide}
            {...restModalProps}
        >
            <Body>
                <PlaybooksSelector
                    teamID={teamId}
                    channelID={triggerChannelId || ''}
                    searchTerm={searchTerm}
                    onSelectPlaybook={handleSelectPlaybook}
                />
            </Body>
        </StyledGenericModal>
    );
};

type RunNameProps = {
    runName: string;
    onSetRunName: (name: string) => void;
    readOnly?: boolean;
};

const RunNameSection = ({runName, onSetRunName, readOnly}: RunNameProps) => {
    const {formatMessage} = useIntl();
    const [error, setError] = useState('');

    const onRunNameChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value;
        if (error && value.length <= RUN_NAME_MAX_LENGTH) {
            setError('');
        } else if (!error && value.length > RUN_NAME_MAX_LENGTH) {
            setError(formatMessage({defaultMessage: 'The run name should not exceed {maxLength} characters'}, {maxLength: RUN_NAME_MAX_LENGTH}));
        }

        onSetRunName(value);
    }, [error, formatMessage, onSetRunName]);

    let suffix = '';
    if (error) {
        suffix = ' ' + formatMessage({defaultMessage: '*'});
    }

    const readOnlyExplanation = formatMessage({defaultMessage: 'The run name is set automatically from this playbook\'s channel name template and can\'t be edited here.'});

    return (<>
        <RunNameLabel invalid={Boolean(error)}>
            {formatMessage(
                {
                    id: 'playbooks.run_playbook_modal.run_name_label',
                    defaultMessage: 'Run name{suffix}',
                },
                {suffix},
            )}
        </RunNameLabel>
        <ConditionalTooltip
            show={Boolean(readOnly)}
            id={'run-name-readonly-tooltip'}
            content={readOnlyExplanation}
        >
            <BaseInput
                $invalid={Boolean(error)}
                $readOnly={readOnly}
                data-testid={'run-name-input'}
                autoFocus={!readOnly}
                type={'text'}
                value={runName}
                readOnly={readOnly}
                aria-describedby={readOnly ? 'run-name-readonly-desc' : undefined}
                onChange={readOnly ? undefined : onRunNameChange}
            />
        </ConditionalTooltip>
        {readOnly && (
            <VisuallyHidden
                id={'run-name-readonly-desc'}
                data-testid={'run-name-readonly-desc'}
            >
                {readOnlyExplanation}
            </VisuallyHidden>
        )}
        {error && <ErrorMessage data-testid={'run-name-error'}>{error}</ErrorMessage>}
    </>);
};

type ChannelProps = {
    teamId: string;
    channelMode: string;
    channelId: string;
    createPublicRun: boolean;
    newChannelOnly?: boolean;
    onSetCreatePublicRun: (val: boolean) => void;
    onSetChannelMode: (mode: 'link_existing_channel' | 'create_new_channel') => void;
    onSetChannelId: (channelId: string) => void;
};

const ConfigChannelSection = ({teamId, channelMode, channelId, createPublicRun, newChannelOnly = false, onSetCreatePublicRun, onSetChannelMode, onSetChannelId}: ChannelProps) => {
    const {formatMessage} = useIntl();
    const createNewChannel = channelMode === 'create_new_channel' || newChannelOnly;
    const linkExistingChannel = channelMode === 'link_existing_channel' && !newChannelOnly;
    return (
        <ChannelContainer>
            {newChannelOnly && (
                <HelpText
                    id='new-channel-only-hint'
                    data-testid='new-channel-only-hint'
                >
                    {formatMessage({defaultMessage: 'This playbook requires a new channel for each run'})}
                </HelpText>
            )}
            <ChannelBlock>
                <StyledRadioInput
                    data-testid={'link-existing-channel-radio'}
                    type='radio'
                    checked={linkExistingChannel}
                    disabled={newChannelOnly}
                    onChange={() => onSetChannelMode('link_existing_channel')}
                />
                <FormattedMessage defaultMessage='Link to an existing channel'/>
            </ChannelBlock>
            {linkExistingChannel && (
                <SelectorWrapper>
                    <StyledChannelSelector
                        id={'link-existing-channel-selector'}
                        data-testid={'link-existing-channel-selector'}
                        onChannelSelected={(channel_id: string) => onSetChannelId(channel_id)}
                        channelIds={channelId ? [channelId] : []}
                        isClearable={true}
                        selectComponents={{ClearIndicator, DropdownIndicator: () => null, IndicatorSeparator: () => null, MenuList}}
                        isDisabled={false}
                        captureMenuScroll={false}
                        shouldRenderValue={true}
                        teamId={teamId}
                        isMulti={false}
                        excludeDMGM={true}
                    />
                </SelectorWrapper>
            )}

            <ChannelBlock >
                <StyledRadioInput
                    data-testid={'create-channel-radio'}
                    type='radio'
                    checked={createNewChannel}
                    onChange={() => onSetChannelMode('create_new_channel')}
                />
                <FormattedMessage defaultMessage='Create a run channel'/>
            </ChannelBlock>

            {createNewChannel && (
                <HorizontalSplit>
                    <VerticalSplit>
                        <ButtonLabel disabled={false}>
                            <RadioInput
                                data-testid={'create-public-channel-radio'}
                                type='radio'
                                checked={createPublicRun}
                                onChange={() => onSetCreatePublicRun(true)}
                            />
                            <Icon
                                $disabled={false}
                                $active={createPublicRun}
                                className={'icon-globe'}
                            />
                            <BigText>{formatMessage({defaultMessage: 'Public channel'})}</BigText>
                        </ButtonLabel>
                        <HorizontalSpacer $size={8}/>
                        <ButtonLabel disabled={false}>
                            <RadioInput
                                data-testid={'create-private-channel-radio'}
                                type='radio'
                                checked={!createPublicRun}
                                onChange={() => onSetCreatePublicRun(false)}
                            />
                            <Icon
                                $disabled={false}
                                $active={!createPublicRun}
                                className={'icon-lock-outline'}
                            />
                            <BigText>{formatMessage({defaultMessage: 'Private channel'})}</BigText>
                        </ButtonLabel>
                    </VerticalSplit>
                </HorizontalSplit>
            )}
        </ChannelContainer>
    );
};

