import React, {useEffect, useMemo, useState} from 'react';
import {useIntl} from 'react-intl';
import ReactSelect, {ActionTypes, ControlProps, StylesConfig} from 'react-select';
import styled from 'styled-components';

import {DateTime, Duration} from 'luxon';
import debounce from 'debounce';

import {Placement} from '@floating-ui/react';

import Dropdown from 'src/components/dropdown';

import {Timestamp} from 'src/webapp_globals';
import {isRtlLocale} from 'src/utils';

import {Option, defaultMakeOptions} from './datetime_input';
import {Mode, parse, parseDateTimes} from './datetime_parsing';

import {LocalizedDuration} from './formatted_duration';

interface ActionObj {
    action: ActionTypes;
}

export type DateTimeOption = Option & {labelRHS?: JSX.Element;}

type Props = {
    testId?: string;
    date?: number;
    mode?: Mode.DateTimeValue | Mode.DurationValue;
    placeholder: React.ReactNode;
    onlyPlaceholder?: boolean;
    suggestedOptions: DateTimeOption[];
    customControl?: (props: ControlProps<DateTimeOption, boolean>) => React.ReactElement;
    controlledOpenToggle?: boolean;
    onSelectedChange: (value: DateTimeOption | undefined | null) => void;
    onOpenChange?: (isOpen: boolean) => void;
    customControlProps?: any;
    placement?: Placement;
    className?: string;

    makeOptions?: (
        query: string,
        datetimeResults: DateTime[],
        durationResults: Duration[],
        mode: Mode,
    ) => Option[] | null;
}

export const optionFromMillis = (ms: number, mode: Mode.DateTimeValue | Mode.DurationValue) => ({
    value: mode === Mode.DateTimeValue ? DateTime.fromMillis(ms) : Duration.fromMillis(ms),
    mode,
});

export const DateTimeSelector = ({
    mode = Mode.DateTimeValue,
    suggestedOptions,
    makeOptions = defaultMakeOptions,
    ...props
}: Props) => {
    const {locale, formatMessage} = useIntl();

    const [isOpen, realSetOpen] = useState(false);
    const setOpen = (open: boolean) => {
        props.onOpenChange?.(open);
        realSetOpen(open);
    };

    const toggleOpen = () => {
        setOpen(!isOpen);
    };

    // Allow the parent component to control the open state -- only after mounting.
    const [oldOpenToggle, setOldOpenToggle] = useState(props.controlledOpenToggle);
    useEffect(() => {
        // eslint-disable-next-line no-undefined
        if (props.controlledOpenToggle !== undefined && props.controlledOpenToggle !== oldOpenToggle) {
            setOpen(!isOpen);
            setOldOpenToggle(props.controlledOpenToggle);
        }
    }, [props.controlledOpenToggle]);

    const onSelectedChange = async (value: DateTimeOption | undefined, action: ActionObj) => {
        if (action.action === 'clear') {
            props.onSelectedChange(null);
            return;
        }
        toggleOpen();
        props.onSelectedChange(value);
    };

    // Seed from suggestedOptions so the menu never renders empty on first paint (useEffect alone runs too late).
    const [options, setOptionsDateTime] = useState<DateTimeOption[]>(suggestedOptions);

    useEffect(() => {
        setOptionsDateTime(suggestedOptions);
    }, [suggestedOptions]);

    let target;
    if (props.onlyPlaceholder) {
        target = (
            <div
                onClick={toggleOpen}
            >
                {props.placeholder}
            </div>
        );
    }
    const targetWrapped = (
        <div
            data-testid={props.testId}
            className={props.className}
        >
            {target}
        </div>
    );

    const updateOptions = useMemo(() => debounce((query: string) => {
        const q = (query || '').trim();
        const datetimes = (parseDateTimes(locale, q) ?? []).map(({start}) => DateTime.fromJSDate(start.date()));
        const duration = parse(locale, q, Mode.DurationValue);
        const made = makeOptions?.(q, datetimes, duration ? [duration] : [], mode);

        // null or [] both mean "no query-derived options" -- fall back to suggestedOptions
        // so the menu never renders empty while the user is typing or after a clear.
        const next = made && made.length > 0 ? made : suggestedOptions;
        setOptionsDateTime(next);
    }, 150), [locale, makeOptions, suggestedOptions, mode]);

    const noDropdown = {DropdownIndicator: null, IndicatorSeparator: null};
    const components = props.customControl ? {
        ...noDropdown,
        Control: props.customControl,
    } : noDropdown;

    return (
        <Dropdown
            isOpen={isOpen}
            onOpenChange={setOpen}
            target={targetWrapped}
            placement={props.placement}

            // react-select is already a combobox/listbox; FloatingFocusManager can hide the
            // menu from the a11y tree in tests (and screen readers) while the menu is open.
            focusManager={false}
            useFloatingRole={false}
        >
            <ReactSelect
                isMulti={false}
                isRtl={isRtlLocale(locale)}
                filterOption={null}
                onInputChange={updateOptions}
                autoFocus={true}
                components={components}
                controlShouldRenderValue={false}
                backspaceRemovesValue={false}
                tabSelectsValue={false}
                hideSelectedOptions={false}
                menuIsOpen={true}
                options={options}
                placeholder={mode === Mode.DateTimeValue ? formatMessage({defaultMessage: 'Specify date/time (“in 4 hours”, “May 1”...)'}) : formatMessage({defaultMessage: 'Specify duration ("8 hours", "3 days"...)'})}
                styles={selectStyles}
                noOptionsMessage={() => <InvalidLabel>{formatMessage({defaultMessage: 'Invalid time duration'})}</InvalidLabel>}
                onChange={onSelectedChange}
                classNamePrefix='playbook-react-select'
                className='playbook-react-select'
                formatOptionLabel={OptionLabel}
                {...props.customControlProps}
            />
        </Dropdown>
    );
};

const TIME_SPEC = {
    useDate: (_: string, {weekday, day, month, year}: any) => ({weekday, day, month, year}),
};

const OptionLabel = ({label, value, mode, labelRHS}: DateTimeOption) => {
    if (label) {
        return (
            <Wrapper>
                {label}
                {labelRHS && <Right>{labelRHS}</Right>}
            </Wrapper>
        );
    }

    if (!value) {
        return null;
    }

    if (mode === Mode.DateTimeValue || (!mode && DateTime.isDateTime(value))) {
        const timestamp = (
            <Timestamp
                value={DateTime.isDateTime(value) ? value : DateTime.now().plus(value)}
                {...TIME_SPEC}
            />
        );
        return (
            <Wrapper>
                {timestamp}
                {labelRHS && <Right>{labelRHS}</Right>}
            </Wrapper>
        );
    }
    return Duration.isDuration(value) && (
        <LocalizedDuration
            value={value}
            unitStyle='long'
        />
    );
};

// styles for the select component
const selectStyles: StylesConfig<DateTimeOption, boolean> = {
    container: (provided) => ({...provided, width: 'min(340px, calc(100vw - 16px))'}),
    control: (provided, state) => ({
        ...provided,
        width: 'calc(100% - 16px)',
        minHeight: 36,
        margin: 8,
        borderColor: state.isFocused ? 'var(--button-bg)' : 'rgba(var(--center-channel-color-rgb), 0.24)',
        backgroundColor: 'var(--center-channel-bg)',
        boxShadow: state.isFocused ? '0 0 0 1px var(--button-bg)' : 'none',
        '&:hover': {borderColor: 'var(--button-bg)'},
    }),
    input: (provided) => ({...provided, color: 'var(--center-channel-color)'}),
    placeholder: (provided) => ({
        ...provided,
        maxWidth: '100%',
        overflow: 'hidden',
        color: 'rgba(var(--center-channel-color-rgb), 0.56)',
        textOverflow: 'ellipsis',
        whiteSpace: 'nowrap',
    }),
    menu: (provided) => ({...provided, width: '100%', margin: 0, backgroundColor: 'var(--center-channel-bg)', boxShadow: 'none'}),
    menuList: (provided) => ({...provided, maxHeight: 'min(260px, 40vh)'}),
    option: (provided, state) => {
        const hoverColor = 'rgba(var(--button-bg-rgb), 0.12)';
        const bgHover = state.isFocused ? hoverColor : 'transparent';
        return {
            ...provided,
            backgroundColor: state.isSelected ? hoverColor : bgHover,
            color: 'var(--center-channel-color)',
        };
    },
};

export default DateTimeSelector;

const Wrapper = styled.div`
    display: flex;
    flex: 1;
    color: var(--center-channel-color);
    font-size: 14px;
    font-weight: 400;
    line-height: 20px;
`;

const Right = styled.div`
    display: flex;
    flex-grow: 1;
    justify-content: flex-end;
`;

const InvalidLabel = styled.span`
    color: var(--error-text);
`;
