import React, {
    ComponentProps,
    useCallback,
    useEffect,
    useMemo,
    useRef,
    useState,
} from 'react';
import {FormattedMessage, useIntl} from 'react-intl';
import debounce from 'debounce';

import {getProfilesInTeam, searchProfiles} from 'mattermost-redux/actions/users';

import styled from 'styled-components';
import {
    AccountMinusOutlineIcon,
    AccountPlusOutlineIcon,
    CheckCircleOutlineIcon,
    PlayIcon,
} from '@mattermost/compass-icons/components';

import {useAppDispatch} from 'src/hooks/redux';

import {FullPlaybook, Loaded, useUpdatePlaybook} from 'src/graphql/hooks';
import {
    fetchPlaybookPropertyFields,
    updatePlaybookChannelNameTemplate,
    updatePlaybookChannelNameTemplateLocked,
    updatePlaybookRunNumberPrefix,
} from 'src/client';
import {usePlaybook as useRestPlaybook} from 'src/hooks/crud';
import {PlaybookWithChecklist} from 'src/types/playbook';
import AutoArchiveToggle from 'src/components/backstage/playbook_editor/auto_archive_toggle';

import {Section, SectionTitle} from 'src/components/backstage/playbook_edit/styles';
import {useToaster} from 'src/components/backstage/toast_banner';
import {ToastStyle} from 'src/components/backstage/toast';
import {InviteUsers} from 'src/components/backstage/playbook_edit/automation/invite_users';
import {AutoAssignOwner} from 'src/components/backstage/playbook_edit/automation/auto_assign_owner';
import {WebhookSetting} from 'src/components/backstage/playbook_edit/automation/webhook_setting';
import {CreateAChannel} from 'src/components/backstage/playbook_edit/automation/channel_access';
import {PROFILE_CHUNK_SIZE} from 'src/constants';

import {Toggle} from 'src/components/backstage/playbook_edit/automation/toggle';
import {AutomationTitle} from 'src/components/backstage/playbook_edit/automation/styles';

import NewChannelOnlyToggle from 'src/components/backstage/playbook_editor/new_channel_only_toggle';

import {useProxyState} from 'src/hooks';
import {getDistinctAssignees} from 'src/utils';
import {mapChecklistItemToInput} from 'src/components/checklist/checklist_list';

interface Props {
    playbook: Loaded<FullPlaybook>;
    canEdit?: boolean;
    newChannelOnly?: boolean;
    onNewChannelOnlyChange?: (updated: {new_channel_only: boolean}) => void;
    restPlaybook?: PlaybookWithChecklist;
    autoArchiveChannel: boolean;
    onAutoArchiveChange: (updated: {auto_archive_channel: boolean}) => void;
}

const LegacyActionsEdit = ({playbook, canEdit = true, newChannelOnly = false, onNewChannelOnlyChange, restPlaybook: restPlaybookProp, autoArchiveChannel, onAutoArchiveChange}: Props) => {
    const [restPlaybookLocal] = useRestPlaybook(playbook.id);
    const restPlaybook = restPlaybookProp ?? restPlaybookLocal;
    const [fieldNames, setFieldNames] = useState<string[] | undefined>(undefined);
    useEffect(() => {
        let cancelled = false;
        setFieldNames(undefined);
        fetchPlaybookPropertyFields(playbook.id)
            .then((fields) => {
                if (!cancelled) {
                    setFieldNames(fields.map((f) => f.name));
                }
            })
            .catch((err) => {
                if (!cancelled) {
                    setFieldNames([]);
                }
                // eslint-disable-next-line no-console
                console.error('Failed to fetch playbook property fields', err);
            });
        return () => {
            cancelled = true;
        };
    }, [playbook.id]);
    const {formatMessage} = useIntl();
    const {add: addToast} = useToaster();
    const addToastRef = useRef(addToast);
    addToastRef.current = addToast;
    const dispatch = useAppDispatch();
    const updatePlaybook = useUpdatePlaybook(playbook.id);
    const archived = playbook.delete_at !== 0;
    const disabled = archived || !canEdit;

    // run_number_prefix is REST-only (not in GraphQL schema). restPlaybook is fetched
    // once and never refreshed, so we track the most recently saved prefix locally and
    // use it as the source of truth — otherwise the prefix field is overwritten with the
    // stale restPlaybook value the next time channelPlaybookSource is recomputed (e.g.
    // after a GraphQL refetch triggered by editing the channel name template).
    const [savedPrefix, setSavedPrefix] = useState(restPlaybook?.run_number_prefix ?? '');
    const savedPrefixRef = useRef(savedPrefix);
    useEffect(() => {
        savedPrefixRef.current = savedPrefix;
    }, [savedPrefix]);
    useEffect(() => {
        setSavedPrefix(restPlaybook?.run_number_prefix ?? '');
    }, [restPlaybook?.run_number_prefix]);

    // channel_name_template_locked is REST-only (not yet in the GraphQL query),
    // tracked the same way as run_number_prefix.
    const [savedTemplateLocked, setSavedTemplateLocked] = useState(restPlaybook?.channel_name_template_locked ?? false);
    const savedTemplateLockedRef = useRef(savedTemplateLocked);
    useEffect(() => {
        savedTemplateLockedRef.current = savedTemplateLocked;
    }, [savedTemplateLocked]);
    useEffect(() => {
        setSavedTemplateLocked(restPlaybook?.channel_name_template_locked ?? false);
    }, [restPlaybook?.channel_name_template_locked]);

    // Merge GraphQL playbook with REST-only fields so CreateAChannel can display run_number_prefix.
    const channelPlaybookSource = useMemo(() => ({
        ...playbook,
        run_number_prefix: savedPrefix,
        next_run_number: restPlaybook?.next_run_number,
        channel_name_template_locked: savedTemplateLocked,
    }), [playbook, savedPrefix, restPlaybook?.next_run_number, savedTemplateLocked]);

    const [
        playbookForCreateChannel,
        setPlaybookForCreateChannel,
    ] = useProxyState<ComponentProps<typeof CreateAChannel>['playbook']>(channelPlaybookSource as ComponentProps<typeof CreateAChannel>['playbook'], useCallback((update) => {
        updatePlaybook({
            createPublicPlaybookRun: update.create_public_playbook_run,
            channelMode: update.channel_mode,
            channelId: update.channel_id,
        });
    }, [updatePlaybook]));

    const handleRunNumberPrefixSave = useMemo(
        () => debounce((prefix: string) => {
            updatePlaybookRunNumberPrefix(playbook.id, prefix)
                .then(() => {
                    setSavedPrefix(prefix);
                })
                .catch((err) => {
                    setPlaybookForCreateChannel((prev) => ({...prev, run_number_prefix: savedPrefixRef.current}));
                    let message: string;
                    if (err?.status_code === 409) {
                        message = formatMessage({defaultMessage: 'Another active playbook in this team already uses that prefix.'});
                    } else if (err?.status_code === 400) {
                        message = formatMessage({defaultMessage: 'Invalid prefix: must start and end with a letter or number and contain only letters, numbers, and hyphens.'});
                    } else {
                        message = formatMessage({defaultMessage: 'Failed to save run number prefix. Please try again.'});
                    }
                    addToastRef.current({content: message, toastStyle: ToastStyle.Failure});
                });
        }, 500),
        [playbook.id, setPlaybookForCreateChannel, formatMessage],
    );

    useEffect(() => {
        return () => handleRunNumberPrefixSave.flush();
    }, [handleRunNumberPrefixSave]);

    // channel_name_template: save via REST PATCH (with server-side validation) instead of GraphQL.
    const lastSavedTemplateRef = useRef(playbook.channel_name_template ?? '');
    useEffect(() => {
        lastSavedTemplateRef.current = playbook.channel_name_template ?? '';
    }, [playbook.channel_name_template]);
    const handleChannelNameTemplateSave = useMemo(
        () => debounce((template: string) => {
            updatePlaybookChannelNameTemplate(playbook.id, template)
                .then(() => {
                    lastSavedTemplateRef.current = template;
                })
                .catch((err) => {
                    setPlaybookForCreateChannel((prev) => ({...prev, channel_name_template: lastSavedTemplateRef.current}));
                    addToastRef.current({
                        content: formatMessage({defaultMessage: 'Failed to save run name template. Please try again.'}),
                        toastStyle: ToastStyle.Failure,
                    });
                    // eslint-disable-next-line no-console
                    console.error('Failed to save channel name template', err);
                });
        }, 500),
        [playbook.id, setPlaybookForCreateChannel, formatMessage],
    );

    useEffect(() => {
        return () => handleChannelNameTemplateSave.flush();
    }, [handleChannelNameTemplateSave]);

    // channel_name_template_locked: debounced the same way as the prefix/template saves above.
    // Debouncing coalesces rapid toggles into a single request, which avoids two overlapping
    // PATCHes resolving out of order — with two in flight at once, a slower one succeeding after
    // a faster one already rolled back could leave the client permanently out of sync with the
    // server until a full reload, since restPlaybook is fetched once and never refreshed.
    const handleChannelNameTemplateLockedSave = useMemo(
        () => debounce((locked: boolean) => {
            updatePlaybookChannelNameTemplateLocked(playbook.id, locked)
                .then(() => {
                    setSavedTemplateLocked(locked);
                })
                .catch((err) => {
                    setPlaybookForCreateChannel((prev) => ({...prev, channel_name_template_locked: savedTemplateLockedRef.current}));
                    addToastRef.current({
                        content: formatMessage({defaultMessage: 'Failed to save this setting. Please try again.'}),
                        toastStyle: ToastStyle.Failure,
                    });
                    // eslint-disable-next-line no-console
                    console.error('Failed to save channel name template locked', err);
                });
        }, 500),
        [playbook.id, setPlaybookForCreateChannel, formatMessage],
    );

    useEffect(() => {
        return () => handleChannelNameTemplateLockedSave.flush();
    }, [handleChannelNameTemplateLockedSave]);

    const preAssignees = useMemo(() => {
        return getDistinctAssignees(playbook.checklists);
    }, [playbook.checklists]);

    const searchUsers = (term: string) => {
        return dispatch(searchProfiles(term, {team_id: playbook.team_id}));
    };

    const getUsers = () => {
        return dispatch(getProfilesInTeam(playbook.team_id, 0, PROFILE_CHUNK_SIZE, '', {active: true}));
    };

    const handleAddUserInvited = (userId: string) => {
        if (!playbook.invited_user_ids.includes(userId)) {
            updatePlaybook({
                invitedUserIDs: [...playbook.invited_user_ids, userId],
            });
        }
    };

    const handleRemoveUserInvited = (userId: string) => {
        const idx = playbook.invited_user_ids.indexOf(userId);
        updatePlaybook({
            invitedUserIDs: [...playbook.invited_user_ids.slice(0, idx), ...playbook.invited_user_ids.slice(idx + 1)],
        });
    };

    const handleRemovePreAssignedUserInvited = (userId: string) => {
        // Iterate all checklists and their tasks and unassign the given user from all tasks
        const checklists = playbook.checklists.map((cl) => ({
            ...cl,
            items: cl.items.map((ci) => ({
                ...mapChecklistItemToInput(ci),
                conditionID: ci.condition_id || '',
                assigneeID: ci.assignee_id === userId ? '' : ci.assignee_id || '',
            })),
        }));
        const idx = playbook.invited_user_ids.indexOf(userId);
        updatePlaybook({
            checklists,
            invitedUserIDs: [...playbook.invited_user_ids.slice(0, idx), ...playbook.invited_user_ids.slice(idx + 1)],
        });
    };

    const handleRemovePreAssignedUsers = () => {
        // Iterate all checklists and their tasks and unassign all assignees
        const checklists = playbook.checklists.map((cl) => ({
            ...cl,
            items: cl.items.map((ci) => ({
                ...mapChecklistItemToInput(ci),
                conditionID: ci.condition_id || '',
                assigneeID: '',
                assigneeType: '',
                assigneePropertyFieldID: '',
            })),
        }));
        updatePlaybook({
            checklists,
            inviteUsersEnabled: false,
        });
    };

    const handleAssignDefaultOwner = (userId: string | undefined) => {
        if ((userId || userId === '') && playbook.default_owner_id !== userId) {
            updatePlaybook({
                defaultOwnerID: userId,
            });
        }
    };

    const handleWebhookOnCreationChange = (urls: string) => {
        updatePlaybook({
            webhookOnCreationURLs: urls.split('\n'),
        });
    };

    const handleToggleInviteUsers = () => {
        updatePlaybook({
            inviteUsersEnabled: !playbook.invite_users_enabled,
        });
    };

    const handleToggleDefaultOwner = () => {
        updatePlaybook({
            defaultOwnerEnabled: !playbook.default_owner_enabled,
        });
    };

    const handleToggleWebhookOnCreation = () => {
        updatePlaybook({
            webhookOnCreationEnabled: !playbook.webhook_on_creation_enabled,
        });
    };

    return (
        <>
            <StyledSection>
                <StyledSectionTitle>
                    <PlayIcon size={24}/>
                    <FormattedMessage defaultMessage='When a run starts'/>
                </StyledSectionTitle>
                <Setting id={'channel-action'}>
                    <CreateAChannel
                        playbook={playbookForCreateChannel}
                        setPlaybook={setPlaybookForCreateChannel}
                        fieldNames={fieldNames}
                        disabled={disabled}
                        onRunNumberPrefixChange={handleRunNumberPrefixSave}
                        onChannelNameTemplateChange={handleChannelNameTemplateSave}
                        onChannelNameTemplateLockedChange={handleChannelNameTemplateLockedSave}
                        newChannelOnly={newChannelOnly}
                    />
                </Setting>
                <Setting id={'new-channel-only'}>
                    <NewChannelOnlyToggle
                        playbook={{new_channel_only: newChannelOnly}}
                        disabled={disabled || !onNewChannelOnlyChange}
                        onChange={onNewChannelOnlyChange}
                    />
                </Setting>
                <Setting id={'invite-users'}>
                    <InviteUsers
                        disabled={disabled}
                        enabled={playbook.invite_users_enabled}
                        onToggle={handleToggleInviteUsers}
                        searchProfiles={searchUsers}
                        getProfiles={getUsers}
                        userIds={playbook.invited_user_ids}
                        preAssignedUserIds={preAssignees}
                        onAddUser={handleAddUserInvited}
                        onRemoveUser={handleRemoveUserInvited}
                        onRemovePreAssignedUser={handleRemovePreAssignedUserInvited}
                        onRemovePreAssignedUsers={handleRemovePreAssignedUsers}
                    />
                </Setting>
                <Setting id={'assign-owner'}>
                    <AutoAssignOwner
                        disabled={disabled}
                        enabled={playbook.default_owner_enabled}
                        onToggle={handleToggleDefaultOwner}
                        searchProfiles={searchUsers}
                        getProfiles={getUsers}
                        ownerID={playbook.default_owner_id}
                        onAssignOwner={handleAssignDefaultOwner}
                    />
                </Setting>
                <Setting id={'playbook-run-creation__outgoing-webhook'}>
                    <WebhookSetting
                        disabled={disabled}
                        enabled={playbook.webhook_on_creation_enabled}
                        onToggle={handleToggleWebhookOnCreation}
                        input={playbook.webhook_on_creation_urls.join('\n')}
                        onBlur={handleWebhookOnCreationChange}
                        pattern={'https?://.*'}
                        delimiter={'\n'}
                        maxLength={1000}
                        rows={3}
                        placeholderText={formatMessage({defaultMessage: 'Enter webhook'})}
                        textOnToggle={formatMessage({defaultMessage: 'Send outgoing webhook (One per line)'})}
                        errorText={formatMessage({defaultMessage: 'Invalid webhook URLs'})}
                        maxRows={64}
                        maxErrorText={formatMessage({defaultMessage: 'Invalid entry: the maximum number of webhooks allowed is 64'})}
                    />
                </Setting>
            </StyledSection>

            <StyledSection>
                <StyledSectionTitle>
                    <AccountPlusOutlineIcon size={22}/>
                    <FormattedMessage defaultMessage='When a participant joins the run'/>
                </StyledSectionTitle>
                <Setting id={'participant-joins-run'}>
                    <AutomationTitle>
                        <Toggle
                            disabled={disabled}
                            isChecked={playbook.create_channel_member_on_new_participant}
                            onChange={() => {
                                updatePlaybook({
                                    createChannelMemberOnNewParticipant: !playbook.create_channel_member_on_new_participant,
                                });
                            }}
                        >
                            <FormattedMessage defaultMessage='Add them to the run channel'/>
                        </Toggle>
                    </AutomationTitle>
                </Setting>
            </StyledSection>

            <StyledSection>
                <StyledSectionTitle>
                    <AccountMinusOutlineIcon size={22}/>
                    <FormattedMessage defaultMessage='When a participant leaves the run'/>
                </StyledSectionTitle>
                <Setting id={'participant-leaves-run'}>
                    <AutomationTitle>
                        <Toggle
                            disabled={disabled}
                            isChecked={playbook.remove_channel_member_on_removed_participant}
                            onChange={() => {
                                updatePlaybook({
                                    removeChannelMemberOnRemovedParticipant: !playbook.remove_channel_member_on_removed_participant,
                                });
                            }}
                        >
                            <FormattedMessage defaultMessage='Remove them from the run channel'/>
                        </Toggle>
                    </AutomationTitle>
                </Setting>
            </StyledSection>
            {restPlaybook && (
                <StyledSection>
                    <StyledSectionTitle>
                        <CheckCircleOutlineIcon
                            size={22}
                            aria-hidden={true}
                        />
                        <FormattedMessage
                            id='V3tvkc'
                            defaultMessage='When a run finishes'
                        />
                    </StyledSectionTitle>
                    <Setting id={'run-finishes'}>
                        <AutomationTitle>
                            <div data-testid='auto-archive-channel-toggle'>
                                <AutoArchiveToggle
                                    autoArchive={autoArchiveChannel}
                                    isLinkedChannel={playbookForCreateChannel.channel_mode === 'link_existing_channel'}
                                    disabled={disabled}
                                    onChange={onAutoArchiveChange}
                                />
                            </div>
                        </AutomationTitle>
                    </Setting>
                </StyledSection>
            )}
        </>
    );
};

export default LegacyActionsEdit;

const StyledSection = styled(Section)`
    padding-block: 2rem;
    padding-inline: 2rem;
    padding-block-end: 0;
    border: 1px solid rgba(var(--center-channel-color-rgb), 0.08);
    border-radius: 8px;
    background-color: var(--center-channel-bg);
    color: var(--center-channel-color);
    margin: 0;
    margin-bottom: 20px;
`;

const StyledSectionTitle = styled(SectionTitle)`
    display: flex;
    align-items: center;
    margin: 0 0 24px;
    font-family: var(--workspace-font-family, "Thmanyah Sans", sans-serif);
    font-size: 16px;
    font-weight: 700;
    gap: 8px;

    svg {
        flex-shrink: 0;
        color: rgba(var(--center-channel-color-rgb), 0.48);
    }
`;

const Setting = styled.div`
    display: flex;
    flex-direction: column;
    margin-bottom: 24px;
    gap: 8px;
`;

