import React from 'react';
import styled, {css} from 'styled-components';

import {KeyVariantCircleIcon} from '@mattermost/compass-icons/components';
import {Button} from '@workspace/shared/components/button';

const workspaceButtonStyle = css`
    height: 40px;
    min-height: 40px;
    gap: 8px;
    padding-block: 0;
    padding-inline: 20px;
    border-radius: 4px;
    font-family: var(--workspace-font-family, "Thmanyah Sans", sans-serif);
    line-height: 20px;
    text-align: center;
    font-size: 14px;
    font-weight: 700;

    i, svg.tabler-icon {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        font-size: 18px;
        line-height: 1;

        &::before {
            margin: 0;
        }
    }

    > svg {
        flex: 0 0 auto;
    }
`;

export const PrimaryButton = styled(Button).attrs({emphasis: 'primary'})`
    ${workspaceButtonStyle}
`;

export const TertiaryButton = styled(Button).attrs({emphasis: 'tertiary'})`
    ${workspaceButtonStyle}
`;

export const SecondaryButton = styled(Button).attrs({emphasis: 'secondary'})`
    ${workspaceButtonStyle}
`;

export const DestructiveButton = styled(Button).attrs({emphasis: 'primary', variant: 'destructive'})`
    ${workspaceButtonStyle}

    && {
        background: rgba(var(--error-text-color-rgb), 0.16);
        color: var(--error-text);
    }

    &&:hover:enabled {
        background: rgba(var(--error-text-color-rgb), 0.24);
    }

    &&:disabled {
        background: rgba(var(--center-channel-color-rgb), 0.08);
        color: rgba(var(--center-channel-color-rgb), 0.48);
    }

`;

export type UpgradeButtonProps = React.ComponentProps<typeof TertiaryButton>;

export const UpgradeTertiaryButton = (props: UpgradeButtonProps & {className?: string}) => {
    const {children, ...rest} = props;
    return (
        <TertiaryButton {...rest}>
            {children}
            <PositionedKeyVariantCircleIcon/>
        </TertiaryButton>
    );
};

const PositionedKeyVariantCircleIcon = styled(KeyVariantCircleIcon)`
    position: absolute;
    top: -4px;
    inset-inline-end: -6px;
    color: var(--online-indicator);
`;

export const ButtonIcon = styled.button`

    display: flex;
    width: 28px;
    height: 28px;
    align-items: center;
    justify-content: center;
    padding-block: 0;
    padding-inline: 0;
    border: none;
    border-radius: 4px;
    background: transparent;
    color: rgba(var(--center-channel-color-rgb), 0.56);
    fill: rgba(var(--center-channel-color-rgb), 0.56);
    font-size: 1.6rem;

    &:hover {
        background: rgba(var(--center-channel-color-rgb), 0.08);
        color: rgba(var(--center-channel-color-rgb), 0.72);
        fill: rgba(var(--center-channel-color-rgb), 0.72);
    }

    &:active,
    &--active,
    &--active:hover {
        background: rgba(var(--button-bg-rgb), 0.08);
        color: var(--button-bg);
        fill: var(--button-bg);
    }
`;
