import React, {ReactNode} from 'react';
import {useIntl} from 'react-intl';
import styled from 'styled-components';

import {Team} from '@mattermost/types/teams';

import {getChannelsNameMapInCurrentTeam} from 'mattermost-redux/selectors/entities/channels';

import {workspaceTypography} from 'src/styles/workspace';
import {isRtlLocale} from 'src/utils';

import {useAppSelector} from 'src/hooks/redux';

import {UpdateBody} from 'src/components/rhs/rhs_shared';

interface Props {
    text: string;
    team: Team;
    children?: ReactNode;
    className?: string;
}

const PostText = (props: Props) => {
    const {locale = 'en'} = useIntl();
    const channelNamesMap = useAppSelector(getChannelsNameMapInCurrentTeam);

    // @ts-ignore
    const {formatText, messageHtmlToComponent} = window.PostUtils;

    const markdownOptions = {
        singleline: false,
        mentionHighlight: true,
        atMentions: true,
        team: props.team,
        channelNamesMap,
    };

    const messageHtmlToComponentOptions = {
        hasPluginTooltips: true,
    };

    return (
        <LocalizedUpdateBody
            className={props.className}
            lang={locale}
            dir={isRtlLocale(locale) ? 'rtl' : 'ltr'}
        >
            {messageHtmlToComponent(formatText(props.text, markdownOptions), true, messageHtmlToComponentOptions)}
            {props.children}
        </LocalizedUpdateBody>
    );
};

const LocalizedUpdateBody = styled(UpdateBody)`
    ${workspaceTypography}
`;

export default PostText;
