const containsEnglishProse = (value: string): boolean => (/[A-Za-z]{3,}[\s,.;:!?]+[A-Za-z]{3,}/).test(value);

type ArabicTemplateField = 'message' | 'summary' | 'reminder' | 'retrospective';

export const localizeStoredTemplateText = (value: string, field: ArabicTemplateField, locale: string): string => {
    if (!value || !locale.toLowerCase().startsWith('ar') || !containsEnglishProse(value)) {
        return value;
    }

    switch (field) {
    case 'message':
        return arabicMessageOnJoin;
    case 'summary':
        return arabicRunSummaryTemplate;
    case 'reminder':
        return arabicReminderMessageTemplate;
    case 'retrospective':
        return arabicRetrospectiveTemplate;
    default:
        return value;
    }
};

const localizeArabicPresetText = (value: string): string => {
    if (arabicPresetText[value]) {
        return arabicPresetText[value];
    }

    const localized = Object.entries(arabicMarkdownText).reduce(
        (translated, [source, translation]) => translated.split(source).join(translation),
        value,
    );

    // Legacy checklist descriptions contain long English prose. Until a dedicated
    // translated description exists, omit that optional text instead of rendering
    // an English paragraph in the Arabic interface.
    return containsEnglishProse(localized) ? '' : localized;
};

// Match complete seeded values, never arbitrary English entered by a user.
const storedPresetText = new Map<string, string>(Object.entries(legacyArabicTemplateText).flatMap(([source, target]) => [
    [source, target ? mtrim(target) : ''],
    [mtrim(source), target ? mtrim(target) : ''],
]));
PresetTemplates.forEach((preset, index) => {
    const translated = ArabicPresetTemplates[index].template;
    const source = preset.template;
    (['title', 'description', 'channel_name_template', 'message_on_join', 'run_summary_template', 'reminder_message_template', 'retrospective_template'] as const).forEach((field) => {
        if (source[field]) {
            storedPresetText.set(source[field], translated[field]);
        }
    });
    source.checklists.forEach((checklist, ci) => {
        storedPresetText.set(checklist.title, translated.checklists[ci].title);
        checklist.items.forEach((item, ii) => {
            const target = translated.checklists[ci].items[ii];
            (['title', 'description', 'command'] as const).forEach((field) => {
                if (item[field]) {
                    storedPresetText.set(item[field], target[field]);
                }
            });
        });
    });
});

storedPresetText.set('اختبار الأخطاء (vX.Y)', 'اختبار الأخطاء (رقم الإصدار)');
storedPresetText.set('الإصدار (vX.Y)', 'الإصدار (رقم الإصدار)');

Object.entries(arabicPresetText).forEach(([source, target]) => {
    if (!storedPresetText.has(source)) {
        storedPresetText.set(source, storedPresetText.get(target) ?? target);
    }
});

export const localizeStoredPresetValue = (value: string, locale: string): string => (
    locale.toLowerCase().startsWith('ar') ? (storedPresetText.get(value) ?? value) : value
);

export const localizeStoredChannelNameTemplate = (value: string, locale: string): string => {
    if (!locale.toLowerCase().startsWith('ar')) {
        return value;
    }

    return localizeStoredPresetValue(localizeArabicPresetText(localizeStoredPresetValue(value, locale)), locale).split('<name>').join('<الاسم>');
};

export const localizePresetTemplate = (inputTemplate: PresetTemplate, intl: IntlShape): PresetTemplate => {
    const sourceKey = inputTemplate.key ?? inputTemplate.title;
    const template = PresetTemplates.find((preset) => preset.title === sourceKey) ?? inputTemplate;
    const descriptor = descriptors[sourceKey];
    if (!descriptor) {
        return template;
    }

    const localized = {
        ...template,
        title: intl.formatMessage(descriptor.title),
        description: intl.formatMessage(descriptor.description),
        label: descriptor.label ? intl.formatMessage(descriptor.label) : template.label,
        template: {
            ...template.template,
            title: intl.formatMessage(descriptor.title),
            description: intl.formatMessage(descriptor.description),
        },
    };

    if (!intl.locale.toLowerCase().startsWith('ar')) {
        return localized;
    }

    const presetIndex = PresetTemplates.findIndex((preset) => preset.title === template.title);
    const arabicTemplate = ArabicPresetTemplates[presetIndex]?.template;
    if (!arabicTemplate) {
        return localized;
    }

    return {
        ...localized,
        template: {
            ...localized.template,
            title: localized.title,
            description: arabicTemplate.description,
            checklists: localized.template.checklists.map((checklist, checklistIndex) => ({
                ...checklist,
                title: arabicTemplate.checklists[checklistIndex].title === 'Default Section' ? 'القسم الافتراضي' : arabicTemplate.checklists[checklistIndex].title,
                items: checklist.items.map((item, itemIndex) => ({
                    ...item,
                    title: arabicTemplate.checklists[checklistIndex].items[itemIndex].title,
                    description: arabicTemplate.checklists[checklistIndex].items[itemIndex].description,
                    command: arabicTemplate.checklists[checklistIndex].items[itemIndex].command,
                })),
            })),
            signal_any_keywords: arabicTemplate.signal_any_keywords,
            channel_name_template: arabicTemplate.channel_name_template,
            message_on_join: arabicTemplate.message_on_join,
            run_summary_template: arabicTemplate.run_summary_template,
            reminder_message_template: arabicTemplate.reminder_message_template,
            retrospective_template: arabicTemplate.retrospective_template,
        },
    };
};
